window.HB_TR["mark"]["ks"]=["1. عیسیٰ مسیح سٕنزِ انجیل ہُند آغاز، یُس خدا سُند فرزند چُھ؛ \n2. یِتھ کٔنۍ پیغمبرن مَنٛز لیکھنہٕ آمُت چُھ، وُچھ، بہٕ چُھس پَنُن پیغامبر تُہٕندِس بُتھِس برونہہ کُن سوزان، یُس تُہٕندِس برونہہ کُن وَتھ تیار کرِ۔ \n3.\\tبیابانس منز کُنہِ کُنہِ سٕنز آواز، خداوند سٕنز وتھ تیار کرٕن، تٔمۍ سٕنزِ وتہٕ کٔرِو سید۔ \n4. یوحنا کٔر بیابانن مَنٛز بپتسمہ دِنہٕ، تہٕ کٔرٕن گۅنہن ہٕنزِ معٲفی خٲطرٕ توبہ کرنٕچ تبلیغ کرنہٕ۔ {for: or, unto}\n5.\\tتہٕ تٔمِس نِش گٔیہِ یہودایہٕچ سٲرٕے زمین، تہٕ یِمو یِمو یروشلمٕکۍ تہٕ سارِوٕے گٔیہِ أمِس سٕندِ دٔریاوٕ اردن مَنٛز بپتسمہ دِنہٕ، تہٕ کٔرِکھ پنٕنـ̡ گۅناہ ہُند اقرار کٔرِتھ۔ \n6. تہٕ یوحنا اوس اونٹِس مَس لٲگِتھ، تہٕ تٔمِس لٔگِس مَلہٕ لٲگِتھ۔ تہٕ تٔمۍ کھیوٚو ٹِڈی تہٕ جنگلی ماچھ۔ \n7.\\tتہٕ وونُن زِ میانہِ کھۅتہٕ زیادٕ طاقتور چُھس یُس میہ پَتہٕ کھۅتہٕ زیادٕ طاقتور چُھس، یٔمۍ سٕندِس کھورِ ہٕندِس لایقَس لایق چھُس نہٕ۔ \n8. بہٕ چُھس پٔزۍ پٲٹھـ̡ ژے آبہٕ سٍتـ̡ بپتسمہ دِژمُت، مگر سُہ کرِ تۅہہِ روح القدس سٍتـ̡ بپتسمہ دِنہٕ۔ \n9. تہٕ تِمن دۅہن سپد عیسیٰ مسیح گلیل کِس ناصرت پیٹھ، تہٕ یوحنا سُند بپتسمہ دِنہٕ آو اردنس مَنٛز۔ \n10.\\tتہٕ سٍتـ̡ آبہٕ منزٕ نیرِتھ وُچھ تٔمِس آسمانس یلہٕ، تہٕ روح کۅتر ہٕندۍ پٲٹھـ̡ وُچھِتھ وُچھمُت: {کھُلنہٕ: یا، ژٔٹِھہ، یا، پھٔٹِھ}\n11. تہٕ آسمانہٕ پیٹھٕ آو اکھ آواز، {ونان}، ژٕ چُھکھ میون ٹٲٹھ نیچو، یٔمِس سٍتـ̡ بہٕ خوش چُھس۔ \n12. تہٕ فوراً چُھ روح أمِس بیابانن مَنٛز نِوان۔ \n13. تہٕ سُہ اوس بیابانس مَنٛز ژتٲجی دۅہہ، شیطان سٕندِ آزمائشس سٍتـ̡ تہٕ اوس جنگلی درندَن سٍتـ̡ سٍتـ̡ تہٕ فرشتو کٔر أمِس خدمت۔ \n14. یێمہِ پَتہٕ یوحنا قٲد خانس مَنٛز تھاونہٕ پتہٕ، عیسیٰ مسیح آو گلیلِس مَنٛز، تہٕ کٔرٕن خدایہِ سٕنزِ بادشٲہی ہٕنزِ خوشخبری ہٕنز تبلیغ کٔرِتھ، \n15. تہٕ ونُن، وقت چُھ پوٗرٕ گومُت، تہٕ خدایہِ سٕنز بادشٲہی چُھ نزدیک: توبہ کٔرِو تہٕ انجیل پیٹھ یقین کرُن۔ \n16.\\tییلہ سُہ گلیل کِس سمندرس کُن پکان اوس تٔمۍ وُچھ شمعون تہٕ اینڈریو سُند بٲے سمندرس منز جال تراوان، تکیازِ تِم ٲسۍ گاڈٕ رٹان۔ \n17. تہٕ حضرت عیسیٰ علیہ السلام ووٚن تِمَن زِ یێلہِ پَتہٕ یِو تہٕ بہٕ بناوٕ ژےٚ انسانن ہٕندِ گاڈٕ رٔٹِتھ ۔ \n18.\\tتہٕ سیدِ سٍتـ̡ ژٔلِتھ تِمو پَنٕنہِ جال ترٲوِتھ أمِس پَتہٕ پَتہٕ۔ \n19.\\tتہٕ ییلہ سُہ اَتہِ رژھ کھنڈ پوٚت پیوٚو، تٔمۍ وُچھ یعقوب زبدی سُند نیچو تہٕ جان تٔمۍ سُند بوے یُس جہازس منز پنُن جال ٹھیک کران اوس۔ \n20.\\tتہٕ تِمو بُلوو تِم پنُن مول زبدی کِس جہازس منز کرایہ دار نوکرَن سٍتـ̡ تہٕ گٔیہِ أمِس پَتہٕ۔ \n21.\\tتہٕ تِم گٔیہِ کِپرنومس مَنٛز۔ تہٕ سبت دۅہہٕ ژاو سُہ یہِ عبادت خانس مَنٛز، تہٕ ہیچھناوُن۔ \n22. تہٕ تِم گٔے تٔمۍ سٕندِس نظریہٕ سٍتـ̡ حٲران: تکیازِ تٔمۍ ہیچھناوُن تِمن أکِس شخصہٕ سٕندِ پٲٹھۍ، یُس اختیار اوس، نہ کہ کاتب سٕندِ پٲٹھۍ۔ \n23. تہٕ تِہٕندِس عبادت خانس مَنٛز اوس اکھ ناپاک روح وول شخٕص۔ تہٕ تٔمۍ کٔر کرٛٮ۪کھ، \n24. وَنُن زِ اسہِ کُنہِ سٍتـ̡ چُھہ اسہِ کیا چُھہ ژے سٍتـ̡ \n25.\\tتہٕ حضرت عیسیٰ علیہ السلامن دِژ أمِس ملامت کٔرِتھ وَنُن زِ پَنُن رٔٹِو تہٕ أمِس نِش نٮ۪بر نیرُن۔ \n26.\\tتہٕ ییلہ ناپاک روحن أمِس ژٔٹِتھ تہٕ بَڑِ آوازِ سٍتـ̡ روُد، سُہ دراو أمِس نِش نٮ۪بر۔ \n27.\\tتہٕ تِم سارِوٕے گٔیہِ حٲران زِ تِمو گٔیہِ پانہٕ أکِس سٍتـ̡ پرژھہٕ، یہِ کیا چُھہ؟ یہِ کُس نۆو عٔقیٖدٕ چُھہ؟ تِکیازِ سُہ چُھ اِختِیار سٍتـ̡ ناپاک روحن تہِ حُکُم دِوان، تہٕ تِم چھِ أمِس فرمانبردار۔ \n28.\\tتہٕ فوراً پھٔہلییہِ تٔمۍ سٕنز شہرت گلیل اندۍ پکھۍ سٲرۍسٕے علاقس منز۔ \n29. تہٕ یێلہِ یێلہِ تِم یہِ عبادت خانہٕ منزٕ نٮ۪بر درایہ، تِم ژاو یعقوب تہٕ یوحنا سٍتـ̡ شمعون تہٕ اینڈریو سٕندِس گرس منز۔ \n30.\\tمگر شمعون سٕنزِ زنانہِ ہٕنز موج ٲس تپھ بٮ۪مار، تہٕ یِمو وَنُن أمِس مُتلِق وَنان۔ \n31.\\tتہٕ سُہ آو أمِس اتھہٕ تھپھ کٔرِتھ تُلِتھ ۔ تہٕ فوراً ووت تٔمِس تپھ تہٕ تٔمۍ کٔر تِمن ہٕنز خدمت۔ \n32.\\tتہٕ ییلہ آفتاب لوسُن، تِمو أنۍ أمِس نِش سٲری بیمار تہٕ یِم شیطان ٲسۍ۔ \n33.\\tتہٕ سورے شہر آو دروازس پیٹھ جمع کرنہٕ۔ \n34.\\tتہٕ تٔمۍ کٔرٕن واریاہن بیمارن ہٕندِس بیمارِ سٍتـ̡ شفا تہٕ کٔرِن واریاہ شیطان۔ تہٕ دِژن نہٕ شیطانن کتھ کرنہٕ خٲطرٕ، تکیازِ تِم ٲسۍ أمِس زانان۔ {کتھ کرُن...: یا یہ ونُن زِ تِم ٲسۍ أمِس زانان}\n35.\\tتہٕ صُبحَس سٍتـ̡ دۅہہٕ سٍتـ̡ وۅتھان بێیہِ سُہ نیبر تہٕ کُنہِ کُنہِ جایہ دراو تہٕ تتہِ کٔرٕن دُعا۔ \n36. تہٕ شمعون تہٕ تِم یِم أمِس سٍتـ̡ ٲسۍ۔ \n37.\\tتہٕ ییلہ تمو أمس لٔبۍ، تمو ووٚن تٔمِس سارِوٕے {انسان} تۅہہِ ژھانڈان۔ \n38. تہٕ تٔمۍ ووٚن تِمن زِ أسۍ گژھو یِنہٕ وٲلِس شہرس مَنٛز، یُتھ بہٕ تتہِ تہِ تبلیغ کٔرِتھ، تِکیازِ بہٕ ووت بہٕ برونہہ کُن۔ \n39.\\tتہٕ تٔمۍ کٔر سٲرۍسٕے گلیل سٕندِس عبادت خانن مَنٛز تبلیغ تہٕ شیطان کٔرِن کٔڑِتھ۔ \n40.\\tتہٕ اَکھ کوڑھ آو أمِس نِش التجا کٔرِتھ تہٕ کٔرِن أمِس نِش کۄٹھہٕ بٔنِتھ تہٕ وونُن زِ اگر ژٕ چاہِ، تہٕ ژٕ ہیکِو مے صاف کٔرِتھ۔ \n41. تہٕ عیسیٰ علیہ السلامن رحم کٔرِتھ ترووُن اتھہٕ تہٕ کوٚرُن أمِس اتھہٕ تہٕ کوٚرُن أمِس وَنُن، بہٕ چُھس کرُن؛ ژٕ گژھہِ پاک ۔ \n42.\\tتہٕ یُتھ أمِس کتھ کٔرِتھ، فوراً گوٚو کوڑھ أمِس نِش تہٕ سُہ گوٚو پاک۔ \n43.\\tتہٕ تٔمۍ کٔر أمِس سختی سان حملہٕ، تہٕ فوراً سوٗزُن سُہ دور۔ \n44.\\tتہٕ چُھہ أمِس وَنُن زِ وُچھِو نہٕ کٲنٛسہِ تہِ کٲنسہِ سٍتـ̡ کُنہِ تہِ وَنُن، مگر پَنٕنـ̡ پَنٕنـ̡ پَنُن پان کٔرِو پادٕرِس نِش، تہٕ تِمن ہٕنزِ گوٲہی دِنہٕ خٲطرٕ کٔرِو تِم چیز یِم موسیٰ سٕندِ حُکُم دِژمٕژ چھِ۔ \n45.\\tمگر سُہ دراو نیبر، تہٕ ہیوٚتُن واریاہ کینہہ شایع کرُن، تہٕ ہیوٚتُن یہِ معاملہٕ نیبر کُن دِنہٕ، یُتھ زن عیسیٰ مسیح ہیوٚک نہٕ شہرس مَنٛز دٲخل گژھِتھ، مگر صحرائی مقامن منز اوس نہٕ دٲخل سپدِتھ، تہٕ تِم ٲسۍ پریتھ طرفہٕ أمِس نِش آمٕتۍ۔","1.\\tتہٕ دُبارٕ ژاو سُہ {کینژَن} دۅہہٕ پَتہٕ کیپرنومس منز۔ تہٕ یہ آو شور زِ سُہ اوس گرس منز۔ \n2.\\tتہٕ سیدِ سٍتـ̡ گٔیہِ واریاہ جمع گٔیہِ، یوت تام زِ تِمن ہٕندِس دروازس اندۍ پکھۍ ٲس نہٕ کانہہ گنجایش، تہٕ تٔمۍ کٔر تِمن کلام تبلیغ۔ \n3.\\tتہٕ تِم چھِ أمِس نِش یِوان أکِس فالج ہٕندِس بیمارس سٍتـ̡ یُس ژورن ہُند زامُت اوس۔ \n4.\\tتہٕ ییلہ تِم أمِس نِش دباونہٕ خٲطرٕ ہیوٚک نہٕ وٲتِتھ، تِمو کٔر سُہ چھت یَتہِ سُہ اوس، تہٕ ییلہ تِمو پھُٹرٲوِتھ، تِمو ترٛٲو سُہ بسترٕ یتھ منز فالج ہٕندِس بیمارس لٔگِتھ اوس۔ \n5. یێلہِ حضرت عیسیٰ علیہ السلام تِہُند ایمان وُچھ، تٔمۍ ووٚن فالج والین بیمارن زِ پٲٹھۍ، تۅہہِ گۅناہ گژھہِ معاف۔ \n6.\\tمگر کاتب ٲسۍ تتہِ بِہتھ تہٕ تِمن ہٕندِس دلس منز استدلال کٔرِتھ، \n7. یہِ {انسان} کیازِ چُھ یِتھٕ پٲٹھۍ کفر کٔرِتھ؟ کُس ہیکہِ صرف خدایہ سٍتـ̡ گۅنہٕ معافی دِتھ؟ \n8. تہٕ یێلہِ عیسیٰ مسیح پننِس روحس مَنٛز وُچھ زِ تِمو چُھ پانس اندر یُتھ استدلال کران، تٔمۍ وۆنُن تِمن کیازِ چُھہ پننین دلن مَنٛز یِمن چیزن ہُند استدلال کران؟ \n9.\\tکیا یہ ونُن چھا سہل زِ تۅہہِ گۅناہ گژھہِ معاف۔ یا یہ ونُن زِ وۅتھ، تہٕ پَنُن بسترٕ رٔٹِتھ پَکُن؟ \n10. مگر تۅہہِ گژھہِ زانُن زِ انسان سُند فرزند چُھ زمینس پیٹھ گۅنہہ معافی دِنُک اختیار تھاوان، (سُہ چُھ فالج ہٕندِس بیمارس ونان )۔\n11. بہٕ چُھس ژے ونان، وۅتھٕ وُتھ، تہٕ پَنُن بسترٕ رٔٹِتھ تہٕ گژھ پنٕنِس گَرَس مَنٛز۔ \n12. تہٕ فوراً ووٚتھ، بسترس تھوٚد تہٕ دراو تِمن سارِنٕے برونہہ کُن۔ یوت تام تِم سٲری حٲران گٔیہِ، تہٕ خدایہ سٕنز حمد کٔرِتھ وونُن زِ اسہِ وُچھ نہٕ یہِ زانہہ یِتھ پٲٹھۍ۔ \n13.\\tتہٕ سُہ دراو بییہ سمندرٕ کِس بٹھس پیٹھ۔ تہٕ سارِوٕے لٔگۍ أمِس سٍتـ̡ ہی \n14.\\tتہٕ ییلہ سُہ اپارِ پکان اوس، تٔمۍ وُچھ الفایوس سُند نیچو لیوی یُس رسم و رواج کِس رسیدس پیٹھ بِہتھ اوس، تہٕ وونُن أمِس پتہٕ۔ تہٕ سُہ ووٚتھ تہٕ أمِس پَتہٕ پَتہٕ۔ {اَتھ جایہِ...: یا تتھ جایہِ ییتہِ یہ رسم آو وصول کرنہٕ}\n15.\\tتہٕ سپُد یہِ زِ یێلہِ عیسیٰ مسیح پننِس گرس مَنٛز مازس پیٹھ بِہتھ، واریاہ پبلکن تہٕ گۅنہگار تہِ بِہتھ عیسیٰ سٕندِس تہٕ تٔمۍ سٕندِس شاگردن سٍتـ̡ تہٕ تِم ٲسۍ أمِس پٲٹھۍ۔ \n16. تہٕ ییلہ کاتبو تہٕ فریسیو أمِس پبلکن تہٕ گۅنہگارن سٍتـ̡ کھیوان وُچھ، تِمو وُچھن پننین شاگردن زِ سُہ کِتھہ کٔنۍ چُھ پبلکارن تہٕ گۅنہگارن سٍتـ̡ کھیوان تہٕ چیوان چُھہ؟ \n17.\\tیێلہِ حضرت عیسیٰ علیہ السلام بوٗزِ، سُہ چُھ تِمن وَنُن زِ یِمن ہٕندِس سارِوٕے سٍتـ̡ چُھہ نہٕ حکیم سٕنز ضرورت، مگر یِم بیمار چِھہ: بہٕ چُھس نہٕ صالحن بُلاونہٕ خٲطرٕ آمُت بلکہ گۅنہگارن توبہ کرنہٕ خٲطرٕ۔ \n18.\\tتہٕ یوحنا تہٕ فریسی سٕندِ شٲگِرِ روزٕ تھاوان، تہٕ تِم چھِ أمِس یِوان تہٕ أمِس ونان زِ یوحنا تہٕ فریسیَن ہٕندِ شٲگِرِ کیازِ چھِ روزٕ تھاوان، مگر تُہند شٲگِر چھُنہٕ روزٕ تھاوان۔ \n19. تہٕ حضرت عیسیٰ علیہ السلام ووٚن تِمن زِ مہرازٕ سٍتـ̡ کیا مہرازٕ سٍتـ̡ روزٕ روزِتھ؟ یوتام نہٕ تِمن سٍتـ̡ مہرازٕ آسہِ، تِم ہیکن نہٕ روزٕ روزِتھ۔ \n20.\\tمگر یِم دۅہ یِن یِمن نِش مہرازٕ نِش نِنہٕ، تہٕ تِمن دۅہن روزٕ روزُن۔ \n21.\\tکانہہ تہِ انسان چھہ نہ پرانہِ پلوس پیٹھ نوو پلو تہِ سِوان: نتہ چھہ نوو پلو یُس اتھ بٔرِتھ آسہِ سہ چھہ پرانہِ نِش نیران، تہ کرایہ چھہ بدتر گژھان۔ {نٔو پلو: یا، خام یا کُنہِ کپر}\n22.\\tتہٕ کانہہ تہِ انسان چُھ نہٕ نوو شراب پرانہِ بوتلن منز تراوان: نتہٕ نٔو شرابہٕ چھُ بوتلہٕ پھٔٹِتھ، تہٕ شراب گژھہِ پھٔٹِتھ، تہٕ بوتلہٕ گژھہِ خراب کرنہٕ: مگر نوو شراب گژھہِ نٔوۍ بوتلن منز تراوُن۔ {بوتلہٕ: یا ژمہِ ہٕندِس بورۍ}\n23.\\tتہٕ سپُد یہِ زِ سبت دۅہہٕ گٔیہِ سُہ مکایہٕ کھہَن مٔنزۍ کٔرِتھ۔ تہٕ تٔمۍ سٕندِس شٲگِرَو گٔیہِ مکایہِ ہٕندِس کُن تُلنہٕ خٲطرٕ۔ \n24. تہٕ فریسیو ووٚن أمِس زِ وُچھِو تِم کیازِ چھِ سبت دۅہہٕ یُس نہٕ حلال چُھ؟ \n25.\\tتہٕ تٔمۍ ووٚن تِمَن زِ کیا چُھہ نہٕ پٔرِمُت زِ داؤدُن کیا کوٚر ، یێلہِ أمِس ضروُرت ٲس تہٕ سُہ تہٕ تِم یِم أمِس سٍتـ̡ ٲسۍ۔ \n26.\\tکِتھہ پٲٹھـ̡ گۆو سُہ خدایہ سٕندِس گرس مَنٛز، یُس نہٕ کھٮ۪نہٕ خٲطرٕ حلال چُھہ بلکہ پادٕرین ہٕندِ خٲطرٕ، تہٕ دِتُن تِمن تہِ یِم أمِس سٍتـ̡ ٲسۍ۔ \n27. تہٕ تٔمۍ ووٚن تِمن زِ سبت اوس انسان سٕندِ خٲطرٕ بناونہٕ آمُت، نہ کہ انسانس خٲطرٕ: \n28. تێمہِ کِنۍ چُھ انسان سُند فرزند تہِ سبت ہُند رب تہِ۔","1. تہٕ سُہ ژاو دُبارٕ یہودی عبادت خانس مَنٛز۔ تہٕ اَتہِ اوس اَکھ شخٕص یٔمِس اَتھٕ ہُند ہُریمُت اوس۔ \n2.\\tتہٕ تِمو وُچھان زِ سبت دۅہہٕ کیا سُہ کرِ أمِس شفا دِنہٕ۔ یُتھ زن تِم أمِس پیٹھ الزام لگٲوِتھ۔ \n3.\\tتہٕ سُہ چُھ أمِس شخصس ونان یٔمِس اَتھٕ مرزاونہٕ آمُت اوس، کھڑا گژھُن۔ {کھڑا گژھُن: Gr. وُتھ، کھڑا گژھُن}\n4.\\tتہٕ سُہ چُھ تِمن ونان زِ کیا سبت دۅہہٕ نیکی کرٕنۍ چھا جٲیز، یا بد کرُن؟ زندگی بچاونہٕ خٲطرٕ، یا مارُن؟ مگر تِمو روٗد پنُن سکون۔ \n5.\\tتہٕ ییلہ تِمن ہٕندِس دِلٕچ سختی ہُند غم گٔژھِتھ غصہٕ سٍتـ̡ تِمن کُن نظر دِژ، سُہ وَنُن أمِس شخصس پَنُن اَتھٕ پھٔہلٲوِو۔ تہٕ تٔمۍ کٔر اَتھٕ دِژُن تہٕ تٔمۍ سُند اَتھٕ گٔیہِ دوٚیمہِ ہٕندۍ پٲٹھۍ۔ {سختی: یا، انہٕ پنُن}\n6. تہٕ فریسی دراو برونہہ کُن، تہٕ سیدِ سٍتـ̡ کٔرٕکھ ہیرودیاہن سٍتـ̡ أمِس خٕلاف مشورٕ، زِ تِم کِتھہٕ کٔنۍ ہیکن أمِس تباہ کٔرِتھ۔ \n7. مگر عیسیٰ مسیح ژاو پننین شاگردن سٍتـ̡ سمندرس کُن، تہٕ گلیل پیٹھٕ تہٕ یہوداہ پیٹھٕ گٔیہِ أمِس پٲٹھۍ، \n8.\\tتہٕ یروشلم پیٹھ، تہٕ ادومیعہ پیٹھ، تہٕ اردن اپارِ پیٹھ۔ تہٕ تِم ٲسۍ صور تہٕ صیدونس متعلق، ییلہ تِمو بوز زِ تٔمۍ کیا بٔڈ کٲم کٔر، أمِس نِش آیہ۔ \n9.\\tتہٕ تٔمۍ ووٚن پننین شاگردن سٍتـ̡ زِ اکھ لۄکُٹ جہازٕ گژھہِ أمِس پیاران یُس بٔڈِس سٍتـ̡ یِمن ہٕندِس بٔڈِس سٍتـ̡ یِمن ہٕندِس بٔڈِس سٍتـ̡ یِمن ہٕندِس سٍتـ̡ \n10.\\tتکیازِ تٔمۍ اوس واریاہن شفا دِژمٕتۍ۔ یوت تام تِمو أمِس اَتھٕ لاگنہٕ خٲطرٕ دباو دِژمُت، تِمن ہٕندِس وُپھ وُپھ دِنہٕ خٲطرٕ۔ {دباونہٕ: یا، جلدٕ}\n11.\\tتہٕ ناپاک روحو ییلہ تمس وُچھ، پیوٚو أمس برونہہ کُن تہٕ وۆنُن تہٕ وۆنُن زِ تہٕ چُھکھ خدایہ سُند نیٚچُو۔ \n12. تہٕ تٔمۍ دِژ سختی سان تمن الزام زِ تِم گژھن نہٕ أمس زاننہٕ۔ \n13. تہٕ سُہ چُھ أکِس پہاڑس پیٹھ کھسان تہٕ أمِس یُس یژھہٕ یژھہٕ بُلاون، تہٕ تِم آیہِ أمِس نِش۔ \n14. تہٕ تٔمۍ دِژ باہ مقرر زِ تِم گژھن أمِس سٍتـ̡ روزن، تہٕ سُہ سوزِ تِمن تبلیغ کرنہٕ خٲطرٕ، \n15. تہٕ بیمارِ ٹھیک کرنُک تہٕ شیطان کڈنہٕ خٲطرٕ طاقت حٲصل کرُن: \n16. تہٕ شمعون اوس پطرس ناو تھوومُت۔ \n17.\\tتہٕ یعقوب سُند نیچو یعقوب تہٕ یوحنا یعقوب سُند بوے ۔ تہٕ تٔمۍ تھوو تِمن بونیرجس ناو، یُس زن گگرٕکۍ نیٚچو: \n18.\\tتہٕ اینڈریو، تہٕ فلپ، تہٕ بارتھولومیو، تہٕ میتھیو، تہٕ تھامس، تہٕ جیمز یُس الفائیس سُند نیچو، تہٕ تھڈیئس، تہٕ شمعون کنعانی، \n19.\\tتہٕ یہوداہ اسکریوٹ، یٔمۍ أمِس تہِ دھوکھہٕ دِژ، تہٕ تِم گٔیہِ أکِس گرس مَنٛز۔ {منز...: یا، گرٕ}\n20.\\tتہٕ لُکھ چُھ دُبارٕ اَکہٕ وٹہٕ یِوان، یێلہِ تِم ہیوٚک نہٕ روٹی کھٮ۪تھ تہِ ہیوٚک نہٕ۔ \n21.\\tتہٕ ییلہ تٔمۍ سٕندِس یارو یہ بوز، تِمو گٔیہِ أمِس تھپھ کرنہٕ خٲطرٕ، تِکیازِ تِمو ووٚن، سُہ چُھ پانس سٍتـ̡ ۔ {دوستو: یا، رشتہٕ دار}\n22.\\tتہٕ یُس کاتب یُس یروشلم پیٹھٕ وسان اوس، تمٔۍ چُھ بعلزبوب تہٕ شیطانن ہٕندِس شہزادس سٍتـ̡ چُھ شیطان کڈان۔ \n23.\\tتہٕ تٔمۍ بُلٲوِتھ تِمن تمثیلن مَنٛز وونُن، شیطان کِتھ کٔنۍ ہیکہِ شیطان کٔرِتھ؟ \n24. تہٕ اگر کانہہ سلطنت پانس خلاف تقسیم کرنہٕ ییہِ، سُہ سلطنت ہیکہِ نہٕ کھڑا گژھِتھ۔ \n25.\\tتہ اگر کانہہ مکانہ پانس خلاف تقسیم کرنہ ییہ، سہ مکانہ ہیکہِ نہ کھڑا گژھتھ۔ \n26. تہٕ یێلہِ شیطان پانس خلاف کھڑا گژھِ، تہٕ تقسیم گژھہِ، سُہ ہیکہِ نہٕ کھڑا گژھِتھ، مگر اکھ خاتمہٕ۔ \n27.\\tکانہہ تہِ انسان ہیکہِ نہٕ أکِس مضبوٗط شخصہٕ سٕندِس گرس منز اژِتھ، تہٕ تٔمۍ سُند مال خراب کٔرِتھ، یوٚت تام سُہ گۅڈٕ طاقتور شخصس پابند کرِ۔ تہٕ پتہٕ کرِ سُہ پنُن گرٕ بِگاڑ۔ \n28. بہٕ چُھس ژےٚ وَنُن زِ اِنسانن ہٕندِس فرزندن ہٕندِس سارِنٕے گۅناہ یِن معاف، تہٕ کُفر یِمن سٍتـ̡ تِم کُفر کَرٕن: \n29. مگر یُس روح القدس خلاف توہین کرِ، تس گژھہِ نہٕ زانہہ معٲفی حٲصل سپدِ، مگر سُہ چُھہ ابدی سزا دِنُک خطرٕ: \n30.\\tکیازِ تِمو چُھ ونان زِ أمِس چُھ ناپاک روح۔ \n31.\\tاَمہِ پتہٕ آیہِ تٔمۍ سٕندِ بٲے تہٕ موج تہٕ سوٗزُن أمِس نِش بُلاونہٕ۔ \n32.\\tتہٕ بٔڈۍ لٔج أمِس اندۍ پکھۍ بِہتھ تہٕ تِمو ووٚنُن تٔمِس وُچھِو، وُچھِو پنٕنۍ موج تہٕ تُہٕندِس بٲے تہٕ تُہٕندِس بٲے سٍتـ̡ تُہٕندِس سٍتـ̡ یێلہِ سٍتـ̡ تُہٕندِس سٍت \n33.\\tتہٕ تٔمۍ دِیُت تِمن جواب دِتھ زِ میانہِ موج کُس چُھ، یا میون بٲے؟ \n34.\\tتہٕ تٔمۍ وُچھن تِمن اندۍ پکھۍ یِم پانس اندۍ پکھۍ بِہتھ ٲسۍ، تہٕ وونُن، وُچھِو میانہِ موج تہٕ میانہِ بٲے ! \n35. یُس تہِ خدایہ سٕنز مرضی کرِ، سُہ چُھ میون بوے تہٕ بینہِ تہٕ موج۔","1. تہٕ تٔمۍ لوٚگ بییہ سمندرس نِش ہیچھناوُن: تہٕ أمِس نِش گٔیہِ واریاہ بٔڈ جمع تہ سُہ ژاو أکِس جہازس منز، تہٕ بیوٹھ سمندرس منز۔ تہٕ سورے لٔج سمندرس کُن زمینس پیٹھ۔ \n2.\\tتہٕ تٔمۍ ہیچھناوُن تمثیلن سٍتـ̡ واریاہ کتھ، تہٕ وونُن تِمن پننِس نظریہس مَنٛز، \n3.\\tبوزُن؛ وُچھِو اَکھ وونہٕ وونہٕ خٲطرٕ: \n4.\\tتہ یہ سپد ییلہ تمۍ وونہِ، کینہہ پیوٚو وتہِ اندۍ پکھۍ، تہ ہوہکۍ جاناوار آیہِ تہ کھیوٚن یہ۔ \n5.\\tتہ کینہہ پیوٚو کنین زمینس پیٹھ، ییتہِ نہ اتھ زیادہ زمین ٲس۔ تہ یکدم ووت یہ پھوٚٹ، تکیازِ اتھ ٲس نہ زمینہِ ہند کانہہ سرٛنٮ۪ر: \n6.\\tمگر ییلہ آفتاب ووٚتھ، سُہ اوس دزمت۔ تہٕ کیازِ أمِس اوس نہٕ کانہہ موٗل ، یہِ گوٚو مرز۔ \n7.\\tتہٕ کینہہ پیوٚو کانٹَن منز، تہٕ کٔرٕکھ کُنہِ تہِ پھلہٕ دِنہٕ۔ \n8.\\tتہٕ باقٕے پیوٚو اصل زمینس پیٹھ، تہٕ دِتُکھ پھل یُس پھوٚل تہٕ ہُرٮ۪ر گوٚو۔ تہٕ کٔرٕن لگ بھگ ترٕہ تہٕ شیٹھ تہٕ کینہہ ہتھ ۔ \n9.\\tتہٕ تٔمۍ ووٚن تِمَن یُس بوزنہٕ خٲطرٕ کَن آسہِ، سُہ بوزُن۔ \n10.\\tتہٕ ییلہ سُہ کُنی اوس، تِم یِم أمِس اندۍ پکھۍ بٔہہ ٲسۍ، تِمو پرژھ أمِس تمثیل۔ \n11. تہٕ تٔمۍ ووٚن تِمَن زِ تۅہہِ چُھہ خدایہِ سٕنزِ بادشٲہی ہُند اسرار زانُن دِنہٕ آمُت، مگر یِمن نیبر چھِ، یِم سارِنٕے چیز چھِ تمثیلن مَنٛز کرنہٕ آمٕتۍ۔ \n12.\\tیُتھ زِ وُچھِن تہٕ وُچھِتھ تہٕ سُہ گژھِ نہٕ سمجُن۔ تہٕ بوزُن تہٕ بوزُن تہٕ تِمن ہٕندِس گۅناہ یِن معاف۔ \n13.\\tتہٕ تٔمۍ ووٚن تِمن زِ کیا تۅہہ چھے نہٕ یہِ تمثیل زانان؟ تہٕ تیلہِ کِتھہٕ کٔنۍ کٔرِو تُہۍ سارِنٕے تمثیلن ہٕنز زان؟ \n14.\\tوودن وول چھہ لفظ ووتمُت۔ \n15. تہٕ یِم چھِ تِم وتہِ نِش یِمن ہُند لفظ وونہٕ آمُت چھُ۔ مگر ییلہ تِمو بوزان چُھ، شیطان چُھ فوراً یِوان تہٕ سُہ لفظ نِوان یُس تِہندِس دِلس مَنٛز وونہٕ آمُت اوس۔ \n16.\\tتہٕ یِم چھِ تِم یِم کٔنہِ زمینہِ پیٹھ وونہٕ آمٕتۍ چھِ۔ یِم یِم لفظ بوزِتھ چھِ یِم خوشی سان قبول کٔرِتھ۔ \n17.\\tتہٕ پانس مَنٛز چُھہ نہٕ کانہہ جڑ آسان، تہٕ یێلہِ چُھہ کُنہِ کالس تام برداشت کران: امہ پتہ ییلہ لفظ سٕندِ خاطرہ مصیبت یا ظلم پٲدٕ سپدِ، فوراً چُھ تِم ناراض سپدان۔ {ناراض: یا، ٹھوکر کھسُن، یا، گۅناہ سٍتـ̡ گۅنہٕ سٍتـ̡ گٔژھِتھ گٔژھِ}\n18.\\tتہٕ یِم چھِ تِم یِم کانٹَن مَنٛز وونہٕ آمٕتۍ چھِ۔ یِمن ہُند کلام بوزان چھُ، \n19.\\tتہٕ یَتھ دُنیاہٕچ فکر، تہٕ دولتٕچ دھوکہٕ، تہٕ باقین چیزن ہٕنزِ ہوس اژنہٕ سٍتـ̡ چُھہ کلامُک دم کٔرِتھ، تہٕ سُہ چُھ بے ثمر گژھان۔ {ہوس: یا، حد کھوتہٕ زیادٕ خواہش}\n20.\\tتہٕ یِم چھِ تِم یِم اصل زمینہِ پیٹھ وونہٕ آمٕتۍ چھِ۔ یِم لفظ بوزان چھِ، تہٕ رٔٹِتھ تہٕ پھل دِوان چھِ، کینہہ ترہ گنہٕ، کینہہ شیٹھ تہٕ کینہہ ہتھ ۔ \n21.\\tتہٕ تٔمۍ ووٚن تِمن زِ شَمَبع چھا بُشلس تَل تھاونہٕ یِنہٕ یا بسترس تَل تھاونہٕ یِن؟ تہٕ شمعدان سٍتـ̡ تھاونہٕ یُن؟ {بُشل: اصلس منز چُھ لفظ کم پیمائش ہُند اشارہ دِوان}\n22.\\tتکیازِ کانہہ تہِ چھُنہٕ پوشید، یُس نہٕ ظٲہر گژھہِ۔ نہ اوس کانہہ چیز راز تھاونہ آمُت، مگر یہ گژھہِ نیبر کُن یُن۔ \n23.\\tاگر کٲنسہِ شخصس بوزنہٕ خٲطرٕ کَن آسہِ، سُہ بوزُن۔ \n24. تہٕ تٔمۍ ووٚن تِمَن زِ یُس تہِ بوزان چھِو تۅہہِ ہُند خیال تھاوُن، تہٕ یُس بوزان چھُو، سُہ گژھہِ تۅہہِ ہٕندِ خٲطرٕ میننہٕ یِنہٕ۔ \n25. یُس نہٕ آسہِ، یُس أمِس نِش دِنہٕ یِیہ، یُس نہٕ أمِس نِش تہِ نِنہٕ یُس أمِس نِش آسہِ۔ \n26.\\tتہٕ ووٚن خدایہِ سٕنز بادشٲہی تہِ، یِتھٕ پٲٹھۍ چُھہ انسان زمینہِ مَنٛز بیول تراوُن۔ \n27.\\tتہٕ گژھہِ شوٚنگُن، تہٕ رٲژ تہٕ دۅہہ، تہٕ بیٲلۍ گژھہِ پھۅلُن تہٕ بڑُن، تس چھیہ نہ خبر۔ \n28.\\tتکیازِ زمینہِ چُھ پانس سٍتـ̡ پھل دِوان۔ گۅڈٕ چُھہ تلوار، پتہٕ کَن، تمہ پتہٕ چُھہ کَنس مَنٛز پوٗرٕ مکایہٕ۔ \n29.\\tمگر ییلہ پھل نیران چھُ، سُہ چُھ فوراً دٲرِ منز تراوان، تکیازِ فصل آو آمُت۔ {اننہٕ...: یا، پۄختہٕ}\n30.\\tتہٕ ووٚن أسۍ کَتھ سٍتـ̡ خدایہِ سٕنزِ بادشٲہی ہٕندِس موازنہٕ سٍتـ̡ ہٲوِو؟ یا أسـ̡ کمہِ سٍتـ̡ موازنہٕ کٔرِو؟ \n31.\\t{یہِ} چُھ سرسٕے دانہٕ ہٕندۍ پٲٹھۍ، یُس زمینہِ مَنٛز وونہٕ یِوان چُھ، تِمو سارِنٕے بیٲلۍ نِش کم آسان چُھ: \n32. مگر ییلہ یہ وونہٕ یِوان چُھ، سُہ چُھ بڑان تہٕ سارِوٕے جڑی بوٹی کھۅتہٕ بٔڈ بنان تہٕ بٔڈۍ لنجہِ نیران۔ یُتھ ہوہٕکۍ جاناوار چھِ اَمہ کِس ژھایہ تل روزان۔ \n33.\\tتہٕ یِتھٮ۪ن تمثیلن سٍتـ̡ ووت تِمن سٍتـ̡ یہِ لفظ، یێلہِ تِم بوزان ٲسۍ۔ \n34.\\tمگر کُنہِ تمثیلہٕ ورٲے اوس نہٕ تِمن سٍتـ̡ کتھ کٔرمٕژ، تہٕ ییلہ تِم کُنی ٲس، تٔمۍ کٔر پننین شاگردن سارِنٕے چیزن ہٕنز وضاحت۔ \n35.\\tتہٕ امی دۅہہ ییلہ تہِ آو، سُہ چُھ تِمن وَنُن زِ أسۍ گژھو دویمِس طرفہٕ نیرُن۔ \n36. تہٕ ییلہ تِمو ہجوم ژوٗر کٔرۍ، تِمو نِش سُہ جہازس منز تہِ۔ تہٕ أمِس سٍتۍ ٲسۍ باقٕے لۄکٕٹۍ جہازٕ تہِ۔ \n37.\\tتہٕ واو ہُند اکھ زبردست طوٗفان، تہٕ لہرٕ لٔج جہازس منز، یُتھ زن وۅنۍ بٔرِتھ اوس۔ \n38.\\tتہٕ سُہ اوس جہازٕ کِس پٔتمِس حصس منز، أکِس تکیہ پیٹھ شوٚنگِتھ، تہٕ تِم چھِ أمِس بیدار کٔرِتھ، تہٕ أمِس وَنُن زِ آقا، ژٕ چھُکھ نہٕ پرواہ کران زِ أسۍ چھِو ہلاک گٔژھان۔ \n39.\\tتہٕ سُہ ووٚتھ، تہٕ واو ہُند ملامت تہٕ وونُن سمندرس سمندرس سٍتۍ، امن، خاموش روزُن۔ تہٕ واو گوٚو رُک، تہٕ اَتہِ گۆو سٮ۪ٹھاہ سکون۔ \n40.\\tتہٕ تِمو گٔیہِ سٮ۪ٹھاہ خوفہٕ تہٕ اَکھ أکِس وونُن، یہِ کُس انسان چُھ، یُس واو تہٕ سمندرٕ تہِ چھُ أمِس فرمانبردار۔","1. تہٕ تِم آیہِ سمندرٕ کِس دوٚیمس اندس کُن، گادارین کِس ملکس منٛز۔ \n2. تہٕ ییلہ سُہ جہازٕ منزٕ نیبر دِنہٕ آو، فوراً ووت قبرو منزٕ اکھ ناپاک روح وول شخٕص، \n3.\\tیُس قبرن منز روزان اوس۔ تہٕ کانہہ تہِ انسان ہیوٚک نہٕ تس زنجیر سٍتۍ بند کٔرِتھ: \n4.\\tتکیازِ أمِس اوس اکثر زنجیر تہٕ زنجیر لٲگِتھ تہٕ زنجیر ژٔٹِتھ ژٔٹِتھ تہٕ زنجیر ژٔٹِتھ ژٔٹِتھ تہٕ زنجیر ژٔٹِتھ تہٕ ہیوٚک نہٕ کٲنسہ تہِ أمِس تھپھ کٔرِتھ۔ \n5. تہٕ ہمیشہٕ رٲژ تہٕ دۄہ اوس سُہ پہاڑن منز، تہٕ قبرن منز، روان تہٕ کٔنہِ سٍتـ̡ ژٹان۔ \n6. مگر ییلہ تٔمۍ عیسیٰ علیہ السلام دور وُچھ، سُہ ژوٚل تہٕ تٔمِس عبادت کٔرٕن، \n7.\\tتہٕ وۆن بَڑِ آوازِ سٍتـ̡ تہٕ وونُن، عیسیٰ مسیح، ژے کیا چُھہ ژے سٍتـ̡ ژے سٍتـ̡ سٍتـ� \n8.\\tتِکیازِ تٔمۍ ووٚن أمِس انسانہٕ سٍتـ̡ نٮ۪بر نیرُن، {ژے} ناپاک روح۔ \n9.\\tتہٕ تٔمۍ پرژھس، تُہند ناو کیا چُھ؟ تہٕ تٔمۍ دیُت جواب دِتھ، میون ناو {چُھ} لشکر: کیازِ أسۍ چھِ واریاہ ۔ \n10. تہٕ تٔمۍ کٔر أمِس سٮ۪ٹھاہ التجا زِ سُہ سوزِ نہٕ تِم مُلکہٕ نیبر۔ \n11.\\tوۅنۍ اوس پہاڑن نکھہ سورن ہُند اکھ بوٚڈ کھیٚول کھیوان۔ \n12. تہٕ سارِوٕے شیطانو کٔر أمِس التجا زِ اسہِ سوز سورس مَنٛز، یُتھ أسۍ تِمن مَنٛز اژِتھ۔ \n13. تہٕ یێلہِ دِژ عیسیٰ علیہ السلامن تِمن رخصت۔ تہٕ ناپاک روح دراو نیبر، تہٕ ژاو سورس منز، تہٕ کھیٚول ژوٚل سمندرس مَنٛز أکِس کھڑایہِ جایہِ پیٹھ، (تِم ٲسۍ لگ بھگ زٕ ساس؛) تہٕ گٔیہٕ سمندرس مَنٛز گُلہٕ دِنہٕ۔ \n14.\\tتہٕ یِمو سورن کھیٚوان دِنہٕ آمٕتۍ ژٔلۍ، تہٕ وونُکھ شہرس تہٕ ملکس مَنٛز۔ تہٕ تِم درٛاو یہِ وٕچھنہٕ خٲطرٕ زِ یہِ کیا چُھ کرنہٕ آمُت۔ \n15. تہٕ تِم آیہ عیسیٰ مسیحس نِش، تہٕ وُچھن سُہ یُس شیطانس سٍتـ̡ اوس، تہٕ لشکر بِہتھ تہٕ پلو لٲگِتھ تہٕ تٔمِس سٕندِس صحیح ذہنس مَنٛز، تہٕ تِم گٔیہِ خوف۔ \n16.\\tتہٕ یِمو وُچھمُت تِمو وُچھ تِمن کِتھہ پٲٹھۍ، یُس شیطانس سٍتـ̡ اوس، تہٕ سورس مُتعلِق تہِ۔ \n17. تہٕ تِمو ہیوٚت أمِس پنہٕ نِس ساحلہٕ نِش نیرنہٕ خٲطرٕ دُعا کرنہٕ۔ \n18. تہٕ ییلہ سُہ جہازس منز آو، یُس شیطانس سٍتـ̡ اوس، تٔمِس کٔر أمِس سٍتـ̡ دُعا زِ سُہ گژھہِ أمِس سٍتـ̡ آسُن۔ \n19. مگر عیسیٰ علیہ السلام کٔر نہٕ أمِس دِنہٕ، مگر چُھس أمِس وَنُن، گَرٕ گژھ پننین دوستن نِش، تہٕ تِمن وَنُن زِ خداوند کِس خٲطرٕ کوتاہ بٔڈ کٲم کٔرمٕژ تہٕ تۅہہِ سٍتـ̡ چُھہ رحم۔ \n20. تہٕ سُہ دراو تہٕ ڈیکاپولسس مَنٛز شایع کرُن شروع زِ عیسیٰ مسیحن کِتھہ پٲٹھۍبٔڈ کٲم ٲس تٔمِس خٲطرٕ کٔرمٕژ: تہٕ سارِوٕے انسانو کٔر حٲران۔ \n21.\\tتہٕ یێلہِ عیسیٰ سُند دُبارٕ جہازٕ سٍتـ̡ دوٚیمہِ طرفہٕ نِنہٕ آو، واریاہ لُکھ گٔیہِ أمِس نِش جمع تہٕ سُہ اوس سمندرس نزدیک۔ \n22.\\tتہٕ وُچھِتھ آو یہِ عبادت خانہٕ کِس حُکُمران سٍتـ̡ یێرس ناو۔ تہٕ ییلہ أمِس وُچھ، سُہ پیوٚو أمِس قدمن پیٹھ، \n23.\\tتہٕ کٔرٕن أمِس سٮ۪ٹھاہ التجا کٔرِتھ زِ میانہِ لۄکٕٹ کورِ چھے مرنہٕ وِزِ لٔگِتھ: {بہٕ چُھس دُعا کٔرِتھ}، یِمو پَنٕنۍ اَتھٕ أمِس پٲٹھۍ، یُتھ سُہ گژھہِ ٹھیٖک سپدِ۔ تہٕ سُہ گژھہِ زندٕ۔ \n24.\\tتہٕ حضرت عیسیٰ سٍتـ̡ گۆو أمِس سٍتـ̡ سٍتـ̡ ۔ تہٕ واریاہ لُکھ لُکھ أمِس پَتہٕ تہٕ گٔیہِ أمِس سٍتـ̡ ہٕندِس سٍتـ� \n25.\\tتہٕ اکھ زنانہٕ، یٔمِس بارہ ؤری خونُک مسلہٕ اوس، \n26.\\tتہٕ ٲسٕن واریاہن طبیبن ہٕندِس سٍتـ̡ واریہن چیزن ہٕندِس سٍتـ̡ تُلنہٕ آمُت، تہٕ سُہ اوس نہٕ بہتر گومُت، بٔلکہِ گٔیہِ بدتر \n27. ییلہ تس عیسیٰ سُند ناو بوز، پٔتۍ کُن آو پریس منز، تہٕ لٔگِن تٔمۍ سٕندِس پلوس اتھہٕ۔ \n28.\\tتکیازِ تٔمۍ ووٚن زِ اگر بہٕ تٔمۍ سٕندِس پلوس اَتھٕ کٔرِتھ، بہٕ گژھہٕ پوٗرٕ پٲٹھۍ۔ \n29.\\tتہ سیدِ سیتۍ گۆو تمۍ سندِ خونُک چشمہ خشک گوو۔ تہ تس گوو پننس جسمس منز احساس زِ سۅ چھیہ تمہِ وبا نشہِ شفا بخشان۔ \n30.\\tتہٕ عیسیٰ علیہ السلام یُس پانس منز فوراً یہ زانان زِ نیکی چھے أمِس نِش نیران، تہٕ وونُن سُہ پریسس مَنٛز پھیُر، تہٕ وونُن، کُس چُھ میٲنس پلوس اتھہٕ لاگمُت؟ \n31.\\tتہٕ تٔمۍ سٕندٮ۪و شٲگِرِیو ووٚن أمِس زِ ژے چھُکھ ژے ہٕندِس بٔڈِس ہٕندِس بٔڈِس سٍتـ̡ وُچھمُت، تہٕ وَنُن چھُکھ میہ کُس اتھہٕ وُچھمُت؟ \n32.\\tتہِ اوس اندۍ پکھۍ نظر دِتھ أمس وُچھان یمۍ یہ کٲم کٔرمٕژ۔ \n33.\\tمگر زنانہِ ہٕندِس خوفہٕ تہٕ تھرتھرس سٍتـ̡ یہ زٲنِتھ زٲنِتھ زِ أمِس منز کیا چُھ سپدمُت، آیہِ أمِس برونہہ کُن پٔسِتھ تہٕ وونُن أمِس سورُے حقیقت۔ \n34. تہٕ تٔمۍ ووٚن أمِس زِ کور، کور، چانہِ ایمانن چُھہ ژے پوٗرٕ پٲٹھۍ۔ امن سان گژھ تہٕ پنہٕ نِس آفتس سٍتـ̡ بٔنِتھ گٔژھِو۔ \n35.\\tییلہ سُہ وُنہِ تہِ کتھ کٔرِتھ، یہِ ووت یہِ عبادت خانہٕ کِس حاکمس سٍتـ̡ یُس وونُن چُھہ تُہٕنز کورِ مٔرۍمٕژ، ژے کیازِ چُھکھ مٲلکِس سٍتـ̡ مزید پریشان کران؟ \n36. یێلہِ حضرت عیسیٰ علیہ السلام سُہ لفظ بوزُن، سُہ وۆن یہِ عبادت خانہٕ کِس حکمرانس ونان، خوفزدہ گژھ نہٕ، صرف ایمان۔ \n37. تہٕ تٔمِس دِژ نہٕ پطرس تہٕ یعقوب سٕندِس بٲیِس تہٕ یوحنا سٕندِس بٲیِس سٍتـ̡ أمِس پتہٕ یِمن سٍتـ̡ پٲٹھ \n38.\\tتہٕ سُہ چُھ یہِ عبادت خانہٕ کِس حکمران سٕندِس گرس منز یِوان، تہٕ وُچھان ہنگامہ تہٕ تِم یِم روُن تہٕ وُچھان چھِ۔ \n39. تہٕ ییلہ سُہ اژان چُھ، سُہ چُھ تِمن وَنُن زِ یێلہِ کیازِ چُھہ یێلہِ دِوان تہٕ رووُن؟ لڑکی چھے نہٕ مٔرِتھ بلکہ شوٚنگِتھ ۔ \n40.\\tتہٕ تِمو کٔر أمِس طنز کرنہٕ خٲطرٕ اسُن۔ مگر ییلہ تٔمۍ سارِنٕے نٮ۪بر کٔرِتھ، سُہ رٔٹِتھ کورِ ہُند مول تہٕ موج تہٕ یِم أمِس سٍتـ̡ ٲس، تہٕ ژاو تتہِ اژان ییتہِ لڑکی ٲس لٔگِتھ۔ \n41.\\tتہٕ تٔمۍ رٔٹِتھ کورِ اَتھٕ تھپھ کٔرِتھ وونُن تٔمِس تلِتھا کُمی۔ یُس ترجمہٕ کٔرِتھ چھُ، لڑکہِ ہُند وَنُن چھُس، وُچھُن وُچھِو۔ \n42.\\tتہٕ سیدِ وَتھ ووٚتھ لڑکی تہٕ پَکُن۔ تکیازِ سۅ ٲس بَہہ ؤری وٲنسہِ۔ تہٕ تِم گٔیہِ سٮ۪ٹھاہ حٲران گٔیہِ۔ \n43.\\tتہٕ تٔمۍ دِیُت تِمن سختی سان حکم زِ کٲنسہ تہِ انسانس گژھہِ یہ زاننہٕ یُن۔ تہٕ دِتُن حکم زِ أمِس گژھہِ کینہہ کھٮ۪نہٕ خٲطرٕ دِنہٕ۔","1. تہٕ سُہ دراو تتہِ پیٹھٕ تہٕ آو پننِس ملکس مَنٛز۔ تہٕ تٔمۍ سٕندِ شٲگِر چھِ أمِس پَتہٕ پٲٹھۍ۔ \n2.\\tتہٕ ییلہ سبت دۅہ آو تٔمۍ کٔر عبادت خانس مَنٛز پرناوُن شروع، تہٕ واریاہ بوزن وٲلِس گٔیہِ حٲران تہٕ وونُن زِ یہِ {انسان} کتہِ چھِ یِم چیز دِنہٕ آمٕتۍ؟ تہٕ یہِ کُس حکمت چھے یُس أمِس دِنہٕ آمُت چھُ، زِ یِتھۍ زبردست کٲم تہِ چھِ تٔمۍ سٕندِ اتھو سٍتـ̡ کرنہٕ آمٕژ۔ \n3. کیا یہِ چھُنہٕ چھان، یُس مریم سُند نیچو، یعقوب سُند بوے تہٕ جوس، تہٕ یہوداہ تہٕ شمعون سُند بوے چُھ؟ تہٕ کیا تٔمۍ سٕنزِ بینہٕ چھے نہٕ اسہِ سٍتـ̡ یێلہِ سٍتـ̡ یێلہِ سٍتـ̡ تٔمِس سٍتـ̡ ناراض گٔیہِ۔ {ناراض: سٍتـ̡ بێیہِ سٍتـ̡ یێلہِ سٍتـ̡ بێیہِ سٍتـ̡ یێلہ\n4. مگر حضرت عیسیٰ علیہ السلام ووٚن تِمن زِ پیغمبر چُھ نہٕ بے عزتی آسان، بلکہ چُھ پننِس ملکس منز، پننین رشتہٕ دارن منز، تہٕ پننِس گرس مَنٛز۔ \n5.\\tتہِ ہیوٚک نہ کانہہ زبردست کٲم کٔرِتھ، مگر تٔمۍ تھووُن کینژَن بیمارن پیٹھ اتھہٕ تہٕ تِمن ٹھیک کٔرِتھ۔ \n6.\\tتہٕ سُہ اوس تِہٕندِ کُفر کِنۍ حٲران گومُت۔ تہٕ سُہ اوس گامن منز نژان پرناوُن۔ \n7.\\tتہٕ تٔمۍ بُلٲوِن بہن تہٕ دِژُن دۄن تہٕ دۄن سٍتـ̡ سوزُن۔ تہٕ دِتُن تِمن ناپاک روحن پیٹھ طاقت۔ \n8.\\tتہٕ دِتُکھ تِمن حُکُم زِ تِم گژھن نہٕ {پنٕنِس} سفرٕ خٲطرٕ کینہہ تہِ نِن، صرف اکھ عصا ورٲے؛ نہ کانہہ سِکرِپ، نہ روٹی تہٕ نہ پٲنسہٕ: {پٲنسہٕ: یہ لفظ چُھ پیتلُک اکھ ٹُکرٕ ظٲہر کران، یُس قٕمتھ اکھ فارتھِنگ کھوتہٕ کم چُھ، مگر یتہِ چُھ یہٕ عام طور پٲنسہٕ خٲطرٕ نِنہٕ یوان}\n9. مگر {be} سینڈل لٲگِتھ تہٕ زٕ کوٹ لاگُن نہٕ۔ \n10.\\tتہٕ تٔمۍ ووٚن تِمن زِ کُنہِ تہِ جایہِ ژاو تہٕ تتہِ روزِو توٚت تام روزُن یوٚت تام نہٕ تَمہِ جایہِ نِش نیرِو۔ \n11. تہٕ یُس نہٕ تۅہہِ رٔٹِتھ تہٕ بوزِ، تہٕ یێلہِ تہٕ تُہۍ نیرِو، تِمن خلاف گوٲہی دِنہٕ خٲطرٕ کٔرِو پننین کھورَن تَل گرد۔ یێلہِ بہٕ چُھس ژےٚ ونان زِ قیامتٕکہِ دۅہہٕ سدوم تہٕ گومورہ ہٕندِ خٲطرٕ روزِ تمہِ شہرٕ کھوتہٕ زیادٕ برداش۔ {تہٕ: Gr. یا}\n12. تہٕ تِمو درٛاو نٮ۪بر، تہٕ تبلیغ کٔرٕکھ زِ انسانس پَزِ توبہ کرُن۔ \n13.\\tتہٕ تِمو کٔرِکھ واریاہ شیطان تہٕ تِمو کٔرِکھ تیٖلہٕ سٍتـ̡ مسح کرنہٕ یِم واریاہ بیمار ٲسۍ، تہٕ کٔرٕکھ شفا ۔ \n14.\\tتہٕ بادشاہ ہیرودیس بوز أمِس مُتلِق۔ (تٔمۍ سُند ناو اوس پردٕ پٲٹھۍ:) تہٕ تٔمۍ ووٚن، یوحنا بپتسمہ دِنہٕ وول اوس مُردٕ منزٕ زندٕ گومُت، تہٕ امہِ مۅکھہ چھِ أمِس مَنٛز زبردست کٲم ظٲہر سپدان۔ \n15.\\tباقیو ووٚن زِ یہ چھہ الیاس۔ تہٕ باقیو ووٚن زِ یہ چھہ پیغمبر یا پیغمبرن منز اکھ ۔ \n16.\\tمگر ییلہ ہیرودیس بوز، تٔمۍ ووٚن، یہ چھُ یوحنا یُس میہ کلہٕ ژٹمُت، سُہ چُھ مُردٕ منزٕ زندٕ گومُت۔ \n17. تکیازِ ہیرودیس اوس پانہٕ یوحنا سٕندِ خٲطرٕ یُس بٲے فلپس سٕنزِ زنانہِ خٲطرٕ اوس سُہ قٲد خانس منز بند کورمُت، تکیازِ تٔمۍ اوس أمِس سٍتـ̡ خاندر کورمُت۔ \n18.\\tکیازِ یوحنا اوس ہیرودیس ووٚنمُت زِ تۅہہِ ہٕندِ خٲطرٕ چُھنہٕ پننِس بٲے سٕنز خانٛدارِنۍ تھاوُن جٲیز۔ \n19.\\tلہذا اوس ہیرودیاسس أمِس خلاف جھگڑا، تہٕ آسِہا أمِس مٲرِتھ۔ مگر سُہ ہیوٚک نہٕ: {اکھ جھگڑہ: یا، اکھ باطنی رنجش}\n20. تکیازِ ہیرودیس اوس یوحنا سُند خوف زٲنِتھ زِ سُہ چُھ اکھ عادل انسان تہٕ پاک، تہٕ کوٚرُن أمِس مُشٲہدٕ۔ تہٕ ییلہ أمِس بوز، تٔمۍ کٔر واریاہ کامہٕ، تہٕ بوزُن أمِس خۄش پٲٹھۍ۔ {أمِس وُچھن: یا، تھووُن أمِس رژھرُن، یا بچٲوِتھ سُہ\n21. تہٕ یێلہِ یێلہِ اَکھ آسان دۅہ آو زِ ہیرودیس کٔر پننِس زاہ دۄہس پیٹھ پننین آقاوَن، تھدِ کپتانن تہٕ گلیل کِس سردارن خٲطرٕ عشائیہٕ۔ \n22.\\tییلہ ہیرودیاس سٕنز کورِ آیہ، تہٕ نژُن تہٕ ہیرودیس تہٕ أمِس سٍتـ̡ بِہنہٕ وٲلِس خۅش کٔرٕن، بادشاہن ووٚن لڑکہِ سٍتـ̡ یێلہِ تہٕ یێلہِ تہٕ بہٕ دِیہٕ ژے دِنہٕ۔ \n23.\\tتہٕ سُہ چُھس أمِس قسم، یُس تہٕ ژٕ میانہِ نِش منگہِ، بہٕ دِیہٕ ژے پننہِ سلطنتُک نصف حصہٕ۔ \n24.\\tتہٕ سۅ گٔیہِ نیبر، تہٕ ووٚننس ماجہ زِ بہٕ کیا پرژھہٕ؟ تہٕ تٔمۍ ووٚن، یوحنا بپتسمہ دِنہٕ وول کلہٕ۔ \n25. تہٕ سۄ آیہِ جلدی سان بادشاہس نِش، تہٕ پرژھن، بہٕ دِژٕ یوحنا بپتسمہ دِنہٕ وول کلہٕ دِنہٕ۔ \n26. تہٕ بادشاہ اوس سٮ۪ٹھاہ معذرت۔ {توتہِ} پنٛنہِ قسمہٕ خٲطرٕ، تہٕ تِہنٛدِ خٲطرٕ یُس أمِس سٍتۍ بِہِتھ، سُہ اوس نہٕ أمِس رَد کَران۔ \n27.\\tتہٕ دِژ بادشاہن جلاد، تہٕ دِتُن أمِس کلہٕ اننُک حُکُم، تہٕ سُہ گوٚو تہٕ جیلس مَنٛز کلہٕ ژٹُن، {an...: یا تٔمۍ سُند اکھ محافظ}\n28.\\tتہٕ اوٚن پنُن کلہٕ أکِس چارجَس منز، تہٕ دیتُن کورِ پننہِ ماجہ دِنہٕ۔ \n29.\\tتہٕ ییلہ تٔمۍ سٕندٮ۪و شاگردو یہِ بوٗز، تِمو آیہِ تٔمۍ سٕنز لاش تُلِتھ قبرس مَنٛز تھووُن۔ \n30. تہٕ رسولو کۆر عیسیٰ ہس نِش جمع تہٕ تمس وونُن سورے چیز، تمو کیا اوس کوٚرمت تہٕ کیا تمو ہیچھناومُت۔ \n31.\\tتہٕ تٔمۍ ووٚن تِمَن زِ یِمو أکِس ریگستانس مَنٛز یِنہٕ تہٕ رٔٹِو کینژَس کالس آرام کٔرِتھ، تِکیازِ واریاہ ٲسۍ یِوان تہٕ یِمن ٲس نہٕ کھٮ۪نہٕ خٲطرٕ کانہہ فرصت آسان۔ \n32.\\tتہٕ تِم دراو ٲبی جہازٕ سٍتـ̡ أکِس ریگستانی مقامس کُن۔ \n33.\\tتہٕ لُکو وُچھ تِم نیران تہٕ واریاہ لٔگۍ أمِس زانان تہٕ سارِوٕے شہرو منزٕ ژٔلِتھ تہٕ تِمن نِش وٲتِتھ گٔیہِ أمِس نِش۔ \n34.\\tتہٕ حضرت عیسیٰ علیہ السلام ییلہ سُہ نیبر آو، وُچھن واریاہ لُکھ تہٕ تِمن سٍتـ̡ ہێکہِ ہمدردی سٍتـ̡ رٔٹِتھ تہٕ تِمن ہٕندِس سٍتـ̡ ہێکہِ ہٕندِس سٍتـ̡ ہێکہِ ہُند ہى۪کان۔ \n35.\\tتہٕ ییلہ دۅہ وُنہِ دۅہ گُزراونہٕ آو، تٔمۍ سٕندِ مرید آیہِ أمِس نِش، تہٕ وونُن زِ یہِ چھُ اَکھ ریگستانی جاے، تہٕ وُنۍ گۆو وق واریاہ دور۔ \n36.\\tتِم سوٗزِو یُتھ تِم اندۍ پکھۍ گٔژِھتھ تہٕ گامن مَنٛز گژھِتھ پانَے روٹی ہینہٕ، تِکیازِ تِمن چُھ نہٕ کھٮ۪نہٕ خٲطرٕ کیٚنٛہہ تہِ۔ \n37.\\tتٔمۍ دِیُت جواب تہٕ وونُن تِمن کھٮ۪نہٕ خٲطرٕ۔ تہٕ تِم چھِ أمِس ونان زِ أسۍ گژھِو زٕ ہتھ پونسہٕ مُلٕچ روٹی اَنِتھ تہٕ دِیِو تِم کھٮ۪نہٕ خٲطرٕ؟ {پینی ورتھ: رومن پونسہٕ چُھ ستھ پینس نصف پونسہٕ}\n38.\\tسُہ چُھ تِمن ونان زِ ژےٚ کٲژاہ روٹی چھِ؟ گژھ تہٕ وُچھ۔ تہٕ ییلہ تِمن پتاہ چُھ، تِم چھِ ونان پانژھ تہٕ زٕ گاڈ۔ \n39.\\tتہٕ تٔمۍ دِیُت تِمن حُکُم زِ تِم کٔرِن سارِنٕے سَبٕز گاسہٕ پٮ۪ٹھ بِہنہٕ۔ \n40. تہٕ تِم بِہتھ تہٕ پنژاہن ہٕندِس صفس منز۔ \n41.\\tتہٕ ییلہ تٔمۍ پانژھ روٹی تہٕ زٕ گاڈٕ رٔٹۍ، تٔمۍ کٔر اسمانس کُن نظر، تہٕ دِژُن برکت، تہٕ دیتُن پننین شاگردن تمن برونہہ کنہِ تھاونہٕ خٲطرٕ۔ تہٕ دۅشوے گاڈٕ کٔر أمس سارِنٕے مَنٛز تقسیم۔ \n42. تہٕ تِمو کٔر سارِنٕے کھٮ۪وان تہٕ بٔرِتھ گٔیہِ۔ \n43.\\tتہٕ تِمو تُل ٹُکرٕ تہٕ گاڈٕ سٍتۍ بٔرِتھ باہ ٹوٗکرۍ۔ \n44.\\tتہٕ یِم روٹی کھٮ۪وان ٲسۍ، تِم ٲسۍ تقریباً پانژھ ساس نفر۔ \n45.\\tتہٕ سٍتـ̡ دِژ تٔمۍ پننین مریدن جہازس منز کھسنہٕ خٲطرٕ مجبور، تہٕ بیتھسیدہ برونہہ کُن گژھن، ییلہ زن تٔمۍ لُکھ ژٔلِتھ دِنہٕ۔ {اُن...: یا، بیت سیداہس خٕلاف}\n46.\\tتہٕ ییلہ تٔمۍ تِم سوزمٕتۍ، سُہ دراو أکِس پہاڑس کُن دعا کرنہٕ خٲطرٕ۔ \n47. تہٕ ییلہ تہِ آو جہازٕ سمندرس منز، تہٕ سُہ اوس کُنی زمینس پیٹھ۔ \n48.\\tتہٕ وُچھ تِم ناوِ چلاونس منز محنت کران۔ تکیازِ واو اوس تِمن برعکس: تہٕ رٲژ ہٕندِس ژورمہِ پہرِ سٍتـ̡ اوس سُہ تِمن نِش سمندرس پیٹھ پکان تہٕ یِمن نِش نیران آسہِ۔ \n49.\\tمگر ییلہ تمو سُہ سمندرس پیٹھ پکان وُچھ، تمو باسیوو زِ یہ چھہ اکھ روح، تہٕ دِژُکھ کرٛٮ۪کھ: \n50.\\tتکیازِ تِمو سارِوٕے وُچھ أمِس تہٕ پریشان گٔیہِ۔ تہٕ فوراً کٔر تِمن سٍتـ̡ کتھ تہٕ وونُن تِمن سٍتـ̡ خوش گژھُن: یہٕ چُھس بہٕ چُھس۔ خوفہٕ گژھ نہٕ۔ \n51.\\tتہٕ سُہ ووت تِمن نِش جہازس منز۔ تہٕ واو گٔیہِ رُک: تہٕ تِم گٔیہِ پانس سٍتۍ حٲران تہٕ حٲران گٔیہِ۔ \n52.\\tتکیازِ تِمو اوس نہٕ روٹین ہُند معجزہ سمجھان، تکیازِ تِہند دِل اوس سخت۔ \n53.\\tتہٕ ییلہ تِم اپارِ گٔیہِ، تِم آیہِ جینیسارٹ کِس سرزمینس منز، تہٕ لٔگۍ بٹھس کُن۔ \n54.\\tتہٕ ییلہ تِم جہازٕ منزٕ نیبر دِنہٕ آیہ، سیدِ سٍتـ̡ گٔیہِ تِم أمِس زانان۔ \n55.\\tتہٕ ژوٚل اَتھ سٲرۍسٕے علاقس منز، تہٕ لوگُن بسترن منز نِنہٕ یِنہٕ وٲلِس بیمارس منز، ییتہِ تِمو بوزان اوس۔ \n56.\\tتہٕ ییتہِ تہِ سُہ گامن یا شہرن یا ملکس منز اژان اوس، تِمو ٲسۍ بیمارن سڑکن منز تراوان تہٕ أمِس التجا کران زِ تِم گژھن اتھہٕ لاگُن، تہٕ یِمو کٔرِن أمِس اَتھٕ لاگنہٕ۔ {اَتھٕ کٔرِتھ: یا اَتھٕ لٔگِتھ}","1. تمہ پتہ آیہ تس نِش فریسی تہٕ کینہہ کاتب یِم یروشلم پیٹھٕ آمٕتۍ ٲسۍ۔ \n2.\\tتہٕ ییلہ تمو وُچھ تٔمۍ سٕندِ کینہہ شٲگِر ناپاک سٍتـ̡ روٹی کھٮ۪وان، یعنی اَتھٕ سٍتـ̡ چُھہ نہٕ وُچھمُت، تِمو لٔبـ̡ عیب ۔ {ناپاک: یا، عام}\n3.\\tفریسیو تہٕ سارِنٕے یہودی خٲطرٕ، یِمن ہٕندِس اتھہٕ چھلنہٕ ورٲے، بزرگن ہٕنز روایت رٔٹِتھ چھِنہٕ کھٮ۪وان۔ {اکثر: یا، محنتہٕ سان: اصلس منز، مٹھی سٍتۍ: تھیوفیلکٹ، کھۄنہٕ تام\n4.\\tتہِ {ییلہ تم بازرِ منزہ یوان چھہِ} چھہِ نہ کھیوان۔ تہ بییہ واریاہ چیز چھہِ، یم یمن رٹنہ خاطرہ میلان چھہِ، مثلا پیالہ تہ بانہ، برتن تہ ٹیبلن چھلن۔ {برتن: سیکسٹیریس چھہ تقریبا ڈۅڈ پِنٹ} {ٹیبل: یا، بستر}\n5.\\tاَمہِ پتہٕ پرژھ فریسی تہٕ کاتب أمِس زِ کیازِ چھُنہٕ پنٕنٮ۪ن شٲگردن بزرگن ہٕندِ روایتہٕ مُطٲبق پکان بلکہ چھلنہٕ آمٕتۍ اتھو سٍتـ̡ روٹی کھٮ۪وان۔ \n6.\\tتٔمۍ دِژ جواب تہٕ وونُن تِمن ہٕندِس بارس مَنٛز یِمن ہٕنز پیشن گویی کٔرمٕژ، یِتھ کٔنۍ چُھ لیکھنہٕ آمُت زِ یِہ لُکھ چُھہ میہ چپنہٕ نِس وٕٹھہٕ سٍتـ̡ عزت دِوان، مگر تِہُند دِل چُھ میانہِ نِش دور۔ \n7. کُنہِ تہِ چھِ تِم میانہِ پوجا کران تہٕ انسانن ہٕندِس حکمس پرناوان چھِ۔ \n8.\\tخدایہ سُند حُکُم ترٲوِتھ چُھہ تُہۍ انسانن ہٕنز روایت تھاوان، یِتھٕ پٲٹھۍ چھِو بانہٕ تہٕ پیالہ چھلناوُن: تہٕ یِتھٕے واریاہ چیٖز تہِ چھِو کران۔ \n9. تہٕ تٔمۍ ووٚن تِمَن زِ تُہۍ چھِو خدایہِ سٕندِس حُکمس پوٗرٕ پٲٹھۍ رد کٔرِتھ، یُتھ زن تُہۍ پنٕنۍ روایت برقرار تھٲوِو۔ {رد کرُن: یا، مایوس}\n10. کیازِ موسىٰ ووٚن زِ پننِس مٲلِس تہٕ ماجہِ ہُند احترام کرُن۔ تہٕ یُس مٲلِس یا ماجہِ بد دُعا کرِ، سُہ گژھہِ مرُن: \n11.\\tتہٕ تہٕ تٔمِس دِیُن نہٕ أمِس مٲلِس یا ماجہ ہٕندِ خٲطرٕ کرُن۔ \n12.\\tپننہِ روایژ سٍتـ̡ خدایہ سُند کلام کُنہِ تہِ اثرس پیٹھ تراوُن، یُس تۅہہ دِژمُت چُھ، تہٕ یِتھۍ واریاہ چیز تہِ کران چھِو۔ \n13.\\tتہٕ ییلہ تٔمۍ سارِنٕے لُکن بُلوو، تٔمۍ ووٚن تِمن سٍتـ̡ تہٕ سمجُن: \n14.\\tانسان سٍتـ̡ چُھہ نہٕ کانہہ تہِ کُنہِ تہِ شخصہٕ سٍتـ̡ یُس أمِس مَنٛز اژِتھ ہیکہِ أمِس ناپاک کٔرِتھ، مگر یِم چیز أمِس نِش نیران چھِ، تِم چھِ تِم انسان ناپاک کٔرِتھ۔ \n15.\\tاگر کٲنسہِ شخصس بوزنہٕ خٲطرٕ کُن آسہِ، سُہ بوزُن۔ \n16.\\tییلہ سُہ لُکہٕ نِش گرس مَنٛز اژنہٕ آو تہٕ تٔمۍ سٕندٮ۪و شٲگِرَو پرژھ أمِس تمثیلَس مُتلِق۔ \n17.\\tتہٕ سُہ چُھ تِمن ونان زِ کیا تُہۍ تہِ چھِو یِتھٕ پٲٹھۍ سمجھنہٕ یِوان؟ کیا تۅہہ چُھہ نہٕ یہِ سمجھان زِ یُس چیز نیبر نیرِتھ انسانس اندر اژان چُھ، سُہ ہیکہِ نہٕ أمِس ناپاک کٔرِتھ۔ \n18.\\tکیازِ یہِ چُھ نہٕ تٔمۍ سٕندِس دِلس مَنٛز اژان بلکہِ یٔڈ مَنٛز دٲخل سپدان تہٕ سارِنٕے ماز صاف کٔرِتھ چُھہ نِش نیران۔ \n19.\\tتہٕ ووٚن یُس انسان سٕندِ نِش نیران چُھ، سُہ چُھ انسانس ناپاک کران۔ \n20.\\tتکیازِ بد خیالات، زنا، زناکاری، قتل، \n21.\\tژورِ، لالچ، بدکاری، دھوکہٕ، بدکاری، بد نظر، کفر، غرور، بیوقوفی: {لالچ...: Gr. لالچ، بدکاری}\n22.\\tیِم سٲری بد کار چھِ أنٛدرِ منزٕ یِوان تہٕ انسانس ناپاک کران۔ \n23.\\tتہٕ تتہِ ووت سُہ ووٚتھ، تہٕ ووت صور تہٕ صیدون کِس سرحدس منز، تہٕ ژاو أکِس مکانس منز، تہٕ اوسُس نہٕ کٲنسہ تہِ پتاہ مگر سُہ ہیوٚک نہٕ ژوٗرِ تھٲوِتھ۔ \n24.\\tأکِس {یقین} زنانہِ خٲطرٕ، یٔمۍ سٕنزِ جوان کورِ ناپاک روح ٲس، تٔمۍ سٕندِس قدمن پیٹھ پیوٚو: \n25. زنانہٕ ٲس اکھ یونانی، قومہٕ لحاظہٕ اکھ سیروفینیشین۔ تہٕ تٔمۍ کٔر أمِس التجا زِ سُہ کٔرِن پننہِ کورِ نِش شیطان کڈنہٕ۔ {یونانی: یا، غیر قوم}\n26. مگر حضرت عیسیٰ علیہ السلام ووٚن أمِس زِ شُرۍ گژھن گۅڈٕ بٔرِتھ بٔرِتھ، تکیازِ شُرین ہُند روٹی نِنہٕ تہٕ ہونین پیٹھ تراوُن چُھہ نہٕ۔ \n27.\\tتہٕ تٔمۍ دیُت جواب تہٕ وونُن أمِس آ، خداوند، توتہِ چھِ ہونۍ دسترَس تَل شُرین ہٕندِ ٹُکرٕ کھیوان۔ \n28.\\tتہٕ تٔمۍ ووٚن أمِس زِ یہِ وَنُن پَنٕنـ̡ وَتھ پٲٹھۍ۔ شیطان چُھہ تُہنزِ کورِ نِش نیبر گومُت۔ \n29.\\tتہٕ ییلہ سۄ پننِس گرس آیہ، أمِس وُچھ شیطان نیبر تہٕ تٔمۍ سٕنز کورِ ٲس بسترس پیٹھ لٔگتھ۔ \n30. تہٕ بییہِ دُبارٕ صور تہٕ صیدون کِس ساحلہٕ پیٹھٕ نیرِتھ ووت سُہ دِکاپولس کِس ساحلس مٔنزۍ گلیل کِس سمندرس کُن۔ \n31.\\tتہٕ تِم چھِ أمِس نِش اکھ زوٚر تہٕ تٔمِس کَتھ باتھہِ مَنٛز رُکاوٹ ٲس۔ تہٕ تِم چھِ أمِس کُن اَتھٕ تھاونٕچ التجا کران۔ \n32.\\tتہٕ تٔمۍ نیو سُہ ہجوم نِش الگ تہٕ کٔرٕن کنن منز اونگجہ تہٕ تھووُن تہٕ تھپھ کٔرِن پننہِ زبانہِ۔ \n33.\\tتہٕ آسمانس کُن نظر دِتھ وۆن أمِس آہ تہٕ وَنُن اِپھتھا، یعنی یلہٕ گژھُن۔ \n34.\\tتہ سیدِ سیدِ تمۍ سٕندِس کَن کھُلنہٕ تہٕ تٔمۍ سٕنزِ زبنہِ ہٕنز تار گٔیہِ، تہٕ تٔمۍ کٔر سیدِ سیدِ کتھ۔ \n35.\\tتہٕ تٔمۍ دِژ تِمن حکم زِ تِم گژھن نہٕ کٲنسہ تہِ کٲنسہ وَنُن: مگر یوتاہ تِمو تِمن ہُند الزام تیوٗت زیادٕ شایع کٔرِتھ۔ \n36.\\tتہٕ گٔے حیران گٔیہِ، یہِ وَنُن زِ تٔمۍ چھُ سارِنٕے کُنہِ چیٖز رٔٹِتھ کٔرمٕژ، سُہ چُھ بہرِ تہٕ کُنہِ تہِ کٔرِتھ دِوان۔","1. تِمن دۅہن ہٕندِس دۅہس منز اوس واریاہ بٔڈ تہٕ کھٮ۪نہٕ خٲطرٕ کینہہ تہِ آسنہٕ کِنۍ، حضرت عیسیٰ علیہ السلام بُلوو پننین شاگردن {پانس کُن}، تہٕ تِمن وَنُن \n2.\\tمیہ چھہ ہجومس پیٹھ رحم تہ تکیازِ تم چھہِ وۅنۍ میہ سیتۍ تریہ دۅہہ، تہ کھٮنہ خاطرہ چھہ نہ کانہہ تہِ۔ \n3.\\tتہٕ اگر بہٕ تِمن پننین گرن منز روزُن سوزان چھُس، تِم گژھن وتہِ وتہِ بیہوش: تِکیازِ یِمو منزٕ چھِ غوطہٕ خور دوٗرِ پیٹھٕ آمٕتۍ۔ \n4.\\tتہٕ تٔمۍ سٕندٮ۪و شٲگِرَو دِیُت أمِس جواب، یَتھ بیابانَس مَنٛز کتہِ ہیکہِ یِمن {انسانَن} ہٕندِس روٹی سٍتـ̡ تسلی دِتھ؟ \n5.\\tتہٕ تٔمۍ پرژھ تمن کٲژاہ روٹۍ؟ تہٕ تِمو ووٚن، سَتھ۔ \n6.\\tتہٕ تٔمۍ دِژ لُکن زمینس پیٹھ بِہنُک حُکُم۔ تہٕ تٔمۍ رٔٹِتھ سَتھ روٹۍ، تہٕ دِتُن شُکریہ ادا تہٕ بریک تہٕ دِتُن پنہٕ نٮ۪ن شاگردن برونہہ کُن تھاونہٕ خٲطرٕ۔ تہٕ تِمو کٔر لُکن برونہہ کُن تھوو۔ \n7.\\tتہٕ تِمن آسہٕ کینہہ لۄکٕٹۍ گاڈٕ: تہٕ تٔمۍ دِژ دُعا دُعا تہٕ دِتُن حُکُم زِ تِم تہِ تھاوُن تِمن برونہہ کُن۔ \n8. تہٕ یِمو کھٮ۪وان ٲسۍ تِم ٲسۍ تقریباً ژور ساس تہٕ تٔمۍ سوٗزۍ تِم ژوٗر ساس ۔ \n9. تہٕ سُہ ژاو سُہ پننین شاگردن سٍتـ̡ أکِس جہازس منز، تہٕ آو ڈلمانوتھا کِس حصس منز۔ \n10. تہٕ فریسی آیہِ برونہہ کُن، تہٕ لوگُکھ أمِس سٍتـ̡ پرژھہٕ گٲر کرنہٕ، تہٕ أمِس سٍتـ̡ آسمانہٕ سٍتـ̡ نشانہٕ ژھارنہٕ خٲطرٕ۔ \n11.\\tتہٕ تٔمۍ کٔر پننِس روحس منز سٮ۪ٹھاہ آہ تہٕ وَنُن زِ یہِ نسل کیازِ چُھ نشانہٕ ژھاران۔ یێلہِ بہٕ چُھس ژے ونان زِ یێمہِ نسلس گژھہِ نہٕ کانہہ نشانی دِنہٕ۔ \n12. تہٕ سُہ ترٲو تِم تہٕ جہازس منز اژِتھ دراو بییہِ طرفہٕ دوٚیمہِ طرفہٕ۔ \n13.\\tوۅنۍ اوس {شاگردن} روٹی نِنۍ مٔشِد گومُت، تہٕ نہ ٲسۍ تِمن سٍتـ̡ اکہِ کھۅتہٕ زیادٕ روٹی ہٕندِس جہازس منز۔ \n14.\\tتہٕ تٔمۍ ووٚن تِمن ہُند حکم دِتھ زِ فریسیین ہٕندِس خمیرس نِش تہٕ ہیرودس سٕندِس خمیرس نِش ہوشیار روزُن۔ \n15.\\tتہٕ تِمو کٔر پانہٕ أکِس سٍتـ̡ استدلال کٔرِتھ، {یہِ} کیازِ اسہِ چُھہ نہٕ کانہہ روٹی ۔ \n16. تہٕ یێلہِ عیسیٰ علیہ السلام پتاہ پتاہ چُھہ، سُہ چُھ تِمن وَنُن، کیازِ چُھہ تۅہہِ کیازِ چُھہ نہٕ روٹی چُھہ؟ تێہہ چُھہ نہٕ وُنیُک تام سمجھان، تہٕ چُھہ نہٕ سمجھان؟ کیا چُھہ وُنہِ تہِ چُھہ دِل سخٕت گومُت؟ \n17.\\tاچھ آسنہ کنۍ چھکھ نہٕ وچھان؟ تہٕ کَن چھکھ نہٕ بوزان؟ تہٕ کیا ژیہ یاد چھُ؟ \n18.\\tییلہ میہ پانژن ساسن منز پانژھ ٹۅکرِ بریک کٔرِتھ، ژیہ کٲژاہ ٹُکرِ بٔرِتھ ژیہ تُلۍ۔ تِم چھِ أمِس ونان باہ۔ \n19. تہٕ ییلہ ژۅن ساسن منز ستھ ژۅن ساس منز، ژیہ کٲژاہ ٹُکرِ بٔرِتھ ژیہ تُلۍ۔ تہٕ تِمو ووٚن ستھ ۔ \n20.\\tتہٕ تٔمۍ ووٚن تِمَن زِ تُہۍ کِتھہ کٔنۍ چُھہ نہٕ سمجھان۔ \n21. تہٕ سُہ آو بیت سیداہس نِش۔ تہٕ تِمو أنۍ أمِس نِش اکھ اوٚن تہٕ أمِس اَتھٕ لاگنہٕ خٲطرٕ التجا کٔرِتھ۔ \n22.\\tتہٕ تٔمۍ رٔٹِتھ انہِ شخصس اتھہٕ تھپھ کٔرِتھ تہٕ نِیوُن شہرٕ منزٕ نٮ۪بر۔ تہٕ ییلہ تٔمۍ أچھن پیٹھ تھوکُن تہٕ أمِس پیٹھ اتھہٕ تھووُن، تٔمۍ پرژھ أمِس زِ کیا وُچھُن پٲٹھۍ۔ \n23.\\tتہٕ تٔمۍ وُچھِتھ وُچھان تہٕ وونُن، بہٕ چھُس انسان کُلٮ۪ن ہٕندۍ پٲٹھۍ، پکان وُچھان۔ \n24.\\tتمہ پتہ تھووُن بییہ اچھن پیٹھ اتھہ تہ ہیوٚر کُن نظر۔ تہ سُہ آو بحال تہ وُچھن پریتھ انسانس صاف پٲٹھۍ۔ \n25.\\tتہٕ سُہ سوٗز سُہ پننِس گَرَس کُن تہٕ وَنُن زِ شہرس مَنٛز گژھ نہٕ تہٕ نہ وَنُن شہرس مَنٛز کٲنٛسہِ۔ \n26.\\tتہٕ عیسیٰ مسیح تہٕ تٔمۍ سٕندِس شٲگِرِد گٔیہِ قیصریہ فِلپی کِس قصبس مَنٛز، تہٕ وَتہٕ وَنُن تٔمۍ پننین شٲگِرن تہٕ تِمن وَنُن زِ بہٕ کُس چُھس ونان چھُس؟ \n27.\\tتہٕ تِمو دِژ جواب، یوحنا بپتسمہ دِنہٕ: مگر کینہہ {وَن}، الیاس۔ تہٕ باقٕے چھِ پیغمبرن مَنٛز اکھ۔ \n28. تہٕ سُہ چُھ تِمن ونان زِ بہٕ کُس چُھس ونان چھُس؟ تہٕ پطرس چُھ جواب دِوان تہٕ أمِس ونان زِ تہٕ چُھہ مسیح چُھس۔ \n29.\\tتہٕ تٔمۍ دِژ تِمن حکم زِ تِم گژھن نہٕ أمِس متعلق کٲنسہ تہِ وَنُن۔ \n30.\\tتہٕ تٔمۍ ہیچھناوُن زِ انسان سُند فرزند گژھہِ واریاہن چیزن ہُند شکار سپدُن، تہٕ بزرگن تہٕ بٔڈۍ پادٕرین تہٕ کاتبن نِش گژھِ رد کرنہٕ یُن، تہٕ مارنہٕ یُن، تہٕ تریہ دۅہہٕ پَتہٕ گژھہِ دُبارٕ وُتھنہٕ یُن۔ \n31.\\tتہٕ تٔمۍ کٔر یہِ کتھ کھلہِ پٲٹھۍ۔ تہٕ پطرس رٔٹِتھ تہٕ ہیوٚتُن أمِس ملامت کرُن۔ \n32.\\tمگر ییلہ سُہ پٔرِتھ پننین شاگردن کُن نظر دِژ، تٔمۍ کٔر پطرس ملامت تہٕ وونُن، شیطان، تہٕ ژے چُھہ نہ خدایہ سٕندِ چیزن سٍتـ̡ لطف اندوز سپدان بلکہ تِمن چیزن ہُند یُس انسانن ہٕندِس چیزس سٍتـ̡ چُھہ آسان۔ \n33.\\tتہٕ ییلہ تٔمۍ پننین شاگردن سٍتـ̡ لُکن بُلوو، تٔمۍ ووٚن تِمن تہٕ یُس تہِ میانہِ پتہٕ یِیہ، سُہ گژھہِ پانس نِش انکار کرُن، تہٕ تُلِن پنُن صلیب تُلِتھ تہٕ میانہِ پتہٕ گژھُن۔ \n34. یُس تہِ پَنُن زُو بچاوِ سُہ گژھہِ سُہ رٲوِ۔ مگر یُس تہِ میانہِ خٲطرٕ تہٕ انجیل ہٕندِ خٲطرٕ پنُن زُو راوِ، سُہ کرِ سُہ بچاوُن۔ \n35.\\tاگر سُہ پورٕ دنیا حٲصل کرِ، تہٕ پنُن روح راوِ تہٕ اَمہ سٍتـ̡ کیا فٲیدٕ واتہِ؟ \n36.\\tیا انسان کیا دِیہِ پننہِ روحہٕ بدلہٕ؟ \n37. یُس تہِ یُس یَتھ زناکار تہٕ گۅنہگار نسلس مَنٛز میانہِ تہٕ میانین کلامَن سٍتـ̡ شرمندہ گژھہِ۔ یێلہِ سُہ یێلہِ سُہ پننِس مٲلہِ سٕندِس جلال سٍتـ̡ پاک فرشتن سٍتـ̡ یِنہٕ سٍتـ̡ یێلہِ سُہ یێلہِ بێیہِ بێیہِ تہٕ بێیہِ سٍتـ̡ شرمندٕ۔","1. تہٕ تٔمۍ ووٚن تِمَن زِ بہٕ چُھس ژےٚ وَنُن زِ یِمو مَنٛز چھِ کینہہ یِم یَتہِ کھڑا چھِ، یِمن نہٕ موتُک مزہ چُھ، یوتام نہٕ تِم خدایہِ سٕنز بادشٲہی طاقتہٕ سٍتـ̡ یِوان وُچھِ۔ \n2. تہٕ شیٚیہِ دۅہہٕ پَتہٕ چُھ عیسیٰ پطرس، یعقوب تہٕ یوحنا پانس سٍتـ̡ نِوان تہٕ تِمن پانَے أکِس تھدِس بالس کُن نِوان تہٕ سُہ آو تِمن برونہہ کُن تبدیٖل کرنہٕ۔ \n3.\\tتہٕ تٔمۍ سُند پوشاک گوٚو شینہٕ ہیوٗ سفید۔ یُتھ زن زمینس پیٹھ کانہہ تہِ پورٕ پوش ہیوٚک نہٕ یمن سفید۔ \n4.\\tتہٕ تِمن نِش آو الیاس موسیٰ سٍتـ̡ ظٲہر تہٕ تِم ٲسۍ عیسیٰ ہس سٍتـ̡ کتھ کران۔ \n5. تہٕ پطرسن دیُت جواب تہٕ ووٚنُن عیسیٰ مسیحس یتہِ آسُن اصل، تہٕ أسۍ بناوو تریہ خیمہ ۔ اکھ تہٕ اکھ موسیٰ سٕندِ خٲطرٕ، تہٕ اکھ الیاس سٕندِ خٲطرٕ۔ \n6.\\tتکیازِ تس کیا چُھ نہٕ وَنُن۔ تِکیازِ تِم ٲسۍ کھوژان۔ \n7.\\tتہٕ اَکھ اوٚبر یُس تِمن ژھایہِ کٔرِتھ اوس، تہٕ اَکھ آواز دراو اوٚبرٕ منز، یہِ چُھ میون پیاری نیچو: بوزو۔ \n8. تہٕ اچانک، ییلہ تِمو اندۍ پکھۍ نظر دِژ، تِمو وُچھ نہٕ کانہہ تہِ انسان، صرف عیسیٰ سٍتـ̡ پانس سٍتـ̡ ۔ \n9.\\tتہٕ ییلہ تِم بالہٕ پیٹھٕ بۄن وٲتۍ، تٔمۍ دِژ تِمن حکم زِ تِم گژھن کٲنسہ تہِ کٲنسہ تہِ وَنُن زِ تِمو کیا چیز وُچھمُت اوس، یوتام نہٕ انسان سُند فرزند مُردٕ منزٕ زندٕ سپدِ۔ \n10.\\tتہٕ تِمو تھوو یہ کتھ پانس سٍتـ̡ تہٕ پرژھان زِ مرنہٕ سٍتـ̡ زندٕ گژھنُک کیا مطلب گژھہِ۔ \n11.\\tتہٕ تِمو پرژھ أمِس زِ کاتب کیازِ چھِ ونان زِ الیاس گژھہِ گۅڈٕ یُن۔ \n12.\\tتہٕ تٔمۍ دِیُت جواب تہٕ وونُن تِمن زِ الیاس چُھ پٔزۍ پٲٹھـ̡ گۅڈٕ یِوان، تہٕ سارِنٕے چیزن ہُند بحال چُھ سپدان۔ تہٕ کِتھہ پٲٹھـ̡ چُھ یہِ لیٚکھنہٕ آمُت زِ أمِس پَزِ واریاہ چیٖز دِنہٕ یُن، تہٕ کُنہِ سٍتـ̡ چُھہ رُکاونہٕ یُن۔ \n13. مگر بہٕ چُھس ژےٚ وَنُن زِ الیاس چُھ پٔزۍ پٲٹھۍ آمُت، تہٕ تِمو چُھ أمِس سٍتـ̡ یُس تہٕ تِمو سٍتـ̡ لیکھنہٕ آمُت چُھ، یِتھ کٔنۍ تٔمِس سٍتـ̡ لیکھنہٕ آمُت چُھ۔ \n14.\\tتہٕ ییلہ سُہ پننین شاگردن نِش آو، تٔمۍ وُچھ تِمن اندۍ پکھۍ واریاہ بٔڈِ، تہٕ کاتب ٲسۍ تِمن سٍتـ̡ پرژھ گٲر کران۔ \n15.\\tتہٕ سٍتـ̡ سارِنٕے لُکھ ییلہ أمِس وُچھِتھ گٔیہِ سٮ۪ٹھاہ حٲران تہٕ دٔلِتھ دِژ أمِس سلام۔ \n16.\\tتہٕ تٔمۍ پُرٛژھ کاتبَن سٍتۍ، تُہۍ کیا سوال چھِو تِمن سٍتۍ؟ {تِمن سٍتۍ: یا پانس منز}\n17.\\tتہٕ اَکہِ بٔڈِس دِژ جواب تہٕ وونُن، آقا، بہٕ چُھس ژے نِش پنُن نیچو اوٚنمُت، یُس گونگا روح چُھ۔ \n18.\\tتہٕ ییتہِ تہِ سُہ أمِس نِوان چھُ، سُہ چھُ ژٔٹِتھ تہٕ دندٕ دِوان تہٕ ژٔٹِتھ دِوان تہٕ چُھس ژٔٹِتھ دِوان۔ تہٕ تِم ہیوٚک نہٕ کٔرِتھ۔ {اوٚش دِنہٕ...: یا چھُ أمِس پھٔٹِتھ دِنہٕ}\n19.\\tسُہ چُھ أمِس جواب دِوان، تہٕ ونان زِ اے بے ایمان نسل، بہٕ کُس کالس روزٕ ژےٚ سٍتۍ؟ بہٕ کُس کالس روزٕ ژےٚ دِنہٕ؟ سُہ أنِو مےٚ نِش۔ \n20.\\tتہٕ تِمو أنۍ أمِس نِش، تہٕ ییٚلہِ أمِس وُچھ، سُہ وُچھُن سُہ وُچھان۔ تہٕ سُہ پیوٚو زٔمیٖنس پیٹھ، تہٕ ووٚتھ دِژُن۔ \n21.\\tتہٕ تٔمۍ پرژھ پننِس مٲلِس زِ یہِ کٲژاہ کال گٔیہِ أمِس نِش آمُت۔ تہٕ تٔمۍ ووٚن، أکِس شُرۍ سٕندِ۔ \n22. تہٕ اکثر چُھ أمِس نارس مَنٛز تہٕ آبس مَنٛز ترٛاوان، تہٕ یێلہِ تہٕ کٔرِو اسہِ سٍتـ̡ رحم تہٕ اسہِ مدد۔ \n23. حضرت عیسیٰ علیہ السلام ووٚن أمِس زِ یێلہِ تہٕ یێلہِ تہٕ یێلہِ تہِ \n24.\\tتہٕ سٍتـ̡ دِژ شُرِ سٕندِس مٲلہِ کٔرِتھ دِژُن تہٕ وونُن اوٚش وُچھِتھ وۆنُن، خداوند، بہٕ چُھس یقین تھاوان۔ میانہِ کُفر کُن کٔرِو مدد۔ \n25.\\tعیسیٰ علیہ السلام وُچھ زِ لُکھ چھِ اَکہٕ وٹہٕ ژلان، تٔمۍ دِژ بدکار روحس ملامت تہٕ وونُن زِ ژے کُنہِ کُنہِ تہٕ بہرِ روح، بہٕ چُھس ژے حکم دِوان، أمِس نِش نیرُن تہٕ تس منز اژُن نہٕ۔ \n26.\\tتہٕ روٝحہِ کٔر دَرٕ، تہٕ دِژ أمِس دَگ تہٕ دِژ أمِس نِش نِش نٮ۪بر، تہٕ سُہ اوس أکِس مُردٕ ہٕندِس پٲٹھۍ۔ یوتاہ واریاہو لوٗکو ووٚن، سُہ چُھ موٗدمُت۔ \n27.\\tمگر حضرت عیسیٰ علیہ السلام رٔٹِتھ تٔمِس اتھہٕ تھپھ کٔرِتھ تُلِتھ تھوٚد۔ تہٕ سُہ ووٚتھُن۔ \n28.\\tتہٕ ییلہ سُہ گرس منز آو تہٕ تٔمۍ سٕندٮ۪و شٲگِرَو پرژھ أمِس خۅد پٲٹھۍ، أسۍ کیازِ ہیوٚک نہٕ أمِس کٔڑِتھ کٔرِتھ؟ \n29. تہٕ تٔمۍ ووٚن تِمن زِ یِہ قٕسمُک یُس نہٕ کُنہِ تہِ سٍتـ̡ سپدِتھ بێیہِ بێیہِ دُعا تہٕ روزٕ سٍتـ̡ سپدِتھ۔ \n30. تہٕ تِم دراو تتہِ تہٕ گلیل کِنۍ گٔیہِ۔ تہٕ سُہ اوس نہٕ یژھان زِ کٲنسہِ انسانس گژھہِ یہ زاننہٕ۔ \n31.\\tتکیازِ تٔمۍ ہیچھناوُن پننین شاگردن تہٕ تِمن وونُن زِ انسان سُند نیچو چُھ انسانن ہٕندِس اتھس منز دِنہٕ آمُت، تہٕ تِم کرِ أمِس مارنہٕ۔ تہٕ تمہ پتہ ییہ سُہ مارنہٕ پتہٕ، سُہ گژھہِ تریمہِ دۅہہ وُتھنہٕ۔ \n32.\\tمگر تِمو ٲس نہٕ یہِ کتھ سمجھ تہٕ تس پرژھنہٕ نِش کھوژان۔ \n33.\\tتہٕ سُہ آو کفرناؤمس نِش تہٕ گرس منز آسنہ کِنۍ پرژھُن تِمن زِ یێلہِ کُس کُنہِ وَتہِ گٔیہِ تۅہہِ پانہٕ وَنُن جھگڑ۔ \n34.\\tمگر تِمو روٗد اَکھ پَنُن اَکھ پٲٹھۍ، یُس سارِوٕے کھۄتہٕ بٔڈ آسُن۔ \n35.\\tتہٕ سُہ بوٚٹھ، تہٕ بُلووُن بہن تہٕ تِمن وونُن زِ اگر کانہہ انسان گۅڈنچہ لٹہِ روزُن یژھان آسہِ، سُہ گژھہِ سارِنٕے سارِنٕے ہُند أخری تہٕ خادم۔ \n36.\\tتہٕ تٔمۍ رٔٹِتھ اکھ شُر، تہٕ تھووُن تِمن منز، تہٕ ییلہ أمِس پنٕنِس نرِ مَنٛز رٔٹِتھ، تٔمۍ ووٚن تِمَن \n37.\\tیُس یُس میانہِ ناوٕ سٍتـ̡ یِتھـ̡ شُرِ سٍتـ̡ میلہِ، سُہ چُھہ میہ رٔٹِتھ تہٕ یُس میہ وصول کرِ، سُہ چُھہ نہٕ میہ رٔٹِتھ بلکہ سُہ یُس میہ سوزمُت چُھ۔ \n38.\\tتہٕ یوحنا دیُت تٔمِس جواب دِتھ وونُن، آقا، اسہِ وُچھ تُہندِ ناوٕ سٍتـ̡ شیطان کڈان تہٕ سُہ چُھنہٕ اسہِ پٲٹھـ̡ پى۪ٹھ۔ \n39.\\tمگر عیسیٰ علیہ السلام ووٚن، تس گژھ نہٕ منع کرنہٕ، تکیازِ کانہہ تہِ انسان چُھہ نہٕ میانہِ ناوٕ سٍتـ̡ معجزہ کٔرِتھ، یُس میانہِ مُتلق ہلکہٕ پٲٹھـ̡ بد کتھ کرِ۔ \n40. یُس نہٕ اسہِ خلاف چُھ، سُہ چُھ سانہِ طرفہٕ ۔ \n41. یُس تہِ میانہِ ناوٕ سٍتـ̡ چنہٕ خٲطرٕ آب پیالہ دِیہِ، کیازِ تہٕ تُہۍ چھِو مسیحس سٍتـ̡ ، یێلہِ بہٕ چُھس ژے ونان زِ سُہ گژھِ نہٕ پَنُن اجر ضایع کرنہٕ۔ \n42.\\tتہٕ یُس تہِ یُس میہ پیٹھ یقین تھاون والیو لۄکٹٮ۪ن منز کٲنٛسہِ ناراض کرِ، تٔمِس خٲطرٕ چُھ بہتر زِ تٔمِس گردنہٕ سٍتـ̡ گٔژھ کٔرِتھ سمندرس مَنٛز دِنہٕ۔ \n43.\\tتہٕ اگر تُہُند اَتھٕ ژٔٹِتھ زِنٛدگی مَنٛز دٲخٕل گٔژھِتھ دِیُن، تَتھ نارس مَنٛز یُس نہٕ زانہہ ژھیتہٕ یِنہٕ: {گُروار...: یا کٔرِو ژےٚ ناراض کرُن}\n44.\\tییتہِ نہٕ تِہُند کیمہٕ مران آسہِ، تہٕ نار چھُنہٕ ژھیتہٕ یِوان کرنہٕ۔ \n45.\\tتہٕ اگر تۅہہِ کھورِ ژٔٹِتھ زِ زٕ کھۅر جہنمس مَنٛز تراونہٕ بجایہ یُس نہٕ زانہہ تہِ ژھیتہِ یِنہٕ یِن: {گُرٕن...: یا ژے کٔرِو تُہٕندِس آزارس منز}\n46.\\tییتہِ نہٕ تِہُند کیمہٕ مران چُھ، تہٕ نار چُھنہٕ ژھیلہٕ یِنہٕ۔ \n47.\\tتہٕ اگر تۅہہِ أچھ ژٔٹِتھ ژٔلِتھ کٔرِو، تۅہہِ کٔرِو اَکہِ أچھ سٍتـ̡ خدایہ سٕندِس بادشاہتس مَنٛز اژُن، زٕ أچھ جہنم کِس نارس مَنٛز تراونہٕ بجایہ چُھہ بہتر زِ تۅہہِ کٔرِو اَکہِ أچھ سٍتـ̡ خدایہِ سٕندِس بادشاہتس مَنٛز اژُن: {بد ظٲہِر...: یا کٔرِو تۅہہِ ناراض کرُن}\n48.\\tییتہِ نہٕ تِہُند کیمہٕ مرُن تہٕ نار چُھ نہٕ ژھیتہٕ گٔژھہِ۔ \n49.\\tپرٮ۪تھ أکِس یِیہِ نارٕ سٍتـ̡ نوٗنہٕ دِنہٕ یُن، تہٕ پرٮ۪تھ کُنہِ قُربٲنی یِیہِ نوٗنہٕ سٍتـ̡ نوٗنہٕ دِنہٕ۔ \n50.\\tنوٗنہٕ چُھہ اصل: مگر اگر نوٗنہٕ نوٗنہٕ ہیوٚت، تیلہِ کَمہِ سٍتۍ کٔرِو تُہۍ اَتھ مَضموٗن۔ نوٗنہٕ تھاوُن پانَس مَنٛز، تہٕ اَکھ أکِس سٍتـ̡ صلح کٔرِو۔","1. تہٕ سُہ ووت اتہِ پیٹھٕ تہٕ آو یہوداہ کِس ساحلس مَنٛز، تہٕ لُکھ دُبارٕ أمِس سٍتـ̡ دُبارٕ سٍتـ̡ پۯاونہٕ آمُت۔ تہٕ یێلہِ أمِ \n2.\\tتہٕ فریسی آیہِ أمِس نِش، تہٕ پرژھن، کیا أکِس مردس خٲطرٕ چُھہ یہ حلال زِ سُہ چُھ پنٕنہِ زنانہٕ دوٗر کٔرِتھ؟ أمِس لالچ دِنہٕ۔ \n3.\\tتہٕ تٔمۍ دِیُت جواب تہٕ وونُن تِمَن زِ موسىٰ کیاہ دِیُت تُہُند حُکُم۔ \n4.\\tتہٕ تِمو ووٚن زِ موسیٰ سُند طلاق نامہٕ لیکھُن تہٕ أمِس دوٗر کرُن۔ \n5.\\tتہٕ حضرت عیسیٰ علیہ السلام دیُت جواب تہٕ وونُن تِمن تہٕ تُہٕندِ دِلٕچ سختی خٲطرٕ لیوکھمُت تٔمۍ چُھہ یہِ حکم۔ \n6.\\tمگر تخلیق کہ آغاز پیٹھے بنوو خداین تم مرد تہٕ زنانہٕ۔ \n7. اَمہ مۅکھہٕ گژھہِ مرد پننِس مٲلِس تہٕ ماجہ ترٲوِتھ پننہِ زنانہِ سٍتـ̡ ژٔٹِتھ روزُن۔ \n8.\\tتہٕ یِم دۅشوے آسن اَکھ ماز تہٕ تیلہِ چھِ نہٕ تِم زٕ بلکہ اکھ ماز۔ \n9.\\tتێلہِ یێمہِ سٍتـ̡ خدایہ یُس رٔلِتھ چُھ، انسان گژھہِ نہٕ الگ الگ کرُن۔ \n10.\\tتہٕ گرس مَنٛز پرژھ تٔمۍ سٕندٮ۪و مرید أمِس بییہِ امی معاملہٕ۔ \n11. تہٕ سُہ چُھ تِمن ونان زِ یُس تہٕ یُس پننہِ زنانہِ ترٲوِتھ بییِس سٍتـ̡ خاندر کرِ، سُہ چُھ أمِس سٍتـ̡ زنا کٔرِتھ۔ \n12. تہٕ اگر زنانہٕ پنُن خانٛدار ترٲوِتھ بییِس سٍتـ̡ خاندر کرِ، سُہ چُھ زنا کَران۔ \n13.\\tتہٕ تِمو أنۍ أمِس نِش لۄکٕٹۍ شُرۍ، یُتھ سُہ تِمن اَتھٕ لاگُن، تہٕ تٔمۍ سٕندٮ۪و شٲگِرَو دِژ تِمن ہٕندِس دِلچس۔ \n14.\\tمگر ییلہ حضرت عیسیٰ علیہ السلام وُچھ، سُہ گوٚو سٮ۪ٹھاہ ناراض، تہٕ تِمن وونُن زِ لۄکٹٮ۪ن شُرین گژھن میانہِ نِش یِن، تہٕ تِمن کٔرِن نہٕ منع کرنہٕ، کیازِ یِمن سٍتـ̡ چُھ خدایہِ سٕنز بادشٲہی ۔ \n15. یێلہِ بہٕ چُھس ژےٚ ونان زِ یُس نہٕ لۄکٹِس شُرِس سٍتـ̡ خدایہِ سٕنز بادشٲہی حٲصل کرِ، سُہ گژھِ نہٕ اَتھ مَنٛز اژُن۔ \n16.\\tتہٕ تٔمۍ تُل تِم پنٕنِس نرِ منز، تھووُن تِمن پیٹھ اتھہٕ تہٕ دِژُن دُعا۔ \n17.\\tتہٕ ییلہ سُہ وتہِ کُن نیرِ، اَکھ آو اَکھ ژٔلِتھ تہٕ کٔرِن أمِس نِش کۄٹھہٕ بٔنِتھ تہٕ پرژھنُن، اَصٕل مالک، بہٕ کیا کٔرٕ بہٕ یُتھ بہٕ ابدی زندگی ہُند وارث میلہِ۔ \n18.\\tتہٕ حضرت عیسیٰ علیہ السلام ووٚن أمِس زِ ژٕ کیازِ چُھکھ میہ نیک وَنان۔ {یێلہِ} چُھہ نہٕ اَکہِ سٍتـ̡ خدایہِ سٍتـ̡ نیکی سٍتـ̡ چُھہ کانہہ تہِ نیکی ۔ \n19. توے چھکھ حُکُم زانان، زنا کرُن نہٕ، قتل مہٕ کرُن، ژوٗرِ نہٕ کرُن، اپُز گوٲہی مہٕ دِیُن، دھوکہٕ دِیُن، مٲلِس ماجہِ ہُند احترام کرُن۔ \n20.\\tتہٕ تٔمۍ دِژ جواب تہٕ وونُن أمِس مالک، یِم سٲری چھِ میہ پننہِ جوانی پیٹھٕ وُچھمٕتۍ۔ \n21. تێمہِ پَتہٕ حضرت عیسیٰ علیہ السلام وُچھِتھ أمِس محبت کٔرِتھ، تہٕ وونُن تٔمِس کُنہِ چیزٕچ کٔمی: پَنٕنہِ وتہِ پٔکِو، یُس تہٕ یێلہِ تہٕ غریبَن دِیُن، تہٕ یێلہِ تُلِو صلیب تُلِتھ تہٕ میانہِ پٲٹھۍ۔ \n22.\\tتہٕ سُہ گوٚو اَتھ کَتھِ پیٹھ غمگیٖن، تہٕ درٛاو غمگیٖن گٔژھِتھ، تکیازِ أمِس اوس واریاہ مالہٕ۔ \n23.\\tتہٕ حضرت عیسیٰ علیہ السلام وُچھ اندۍ پکھۍ نظر تہٕ پننین شاگردن وونُن زِ یِم دولت تھاون وٲلِس خدایہ سٕندِس بادشٲہی مَنٛز کوتاہ مشکل گژھن دٲخل! \n24. تہٕ شٲگِر گٔیہِ تٔمۍ سٕندِس کلامَس پیٹھ حٲران۔ مگر عیسیٰ مسیح دِیُت دُبارٕ جواب تہٕ تِمن وَنُن زِ بچہٕ، خدایہِ سٕنزِ بادشٲہی مَنٛز دٲخل گژھُن کوتاہ چُھ تِمن خٲطرٕ مُشکِل! \n25.\\tاونٹِس خٲطرٕ چُھ سٕژنہِ ہٕندِ أچھ منزٕ نیرُن آسان یُس أکِس امیر شخصہٕ سٕندِ خٲطرٕ خدایہ سٕندِس بادشاہتس مَنٛز اژُن۔ \n26.\\tتہٕ تِم گٔیہِ حٲران تہٕ وونُکھ پانہٕ وٲنِتھ، تیلہِ کُس ہیکہِ نجات دِنہٕ یِتھ؟ \n27. تہٕ عیسیٰ مسیح چُھ تِمن وُچھِتھ ونان زِ انسانس سٍتـ̡ چُھہ ناممکن، مگر خدایہ سٍتـ̡ چُھہ نہٕ سارِنٕے چیزن مُمکِن۔ \n28. پطرس ہیوٚت أمِس وَنُن، لو، أسۍ چھِ سارِوٕے ترٲومٕتۍ، تہٕ چُھکھ تۅہہِ پتہٕ پٲٹھۍ۔ \n29. تہٕ حضرت عیسیٰ علیہ السلام دیُت جواب تہٕ وونُن، پٔزۍ پٲٹھـ̡ چُھس بہٕ چُھس ژے وَنُن، یُس نہٕ کانہہ تہِ انسان چُھہ یُس میانہِ خٲطرٕ تہٕ انجیل ہٕندِ خٲطرٕ گَر، یا بٲے، یا بینہِ، یا مٲلِس، یا ماجہ، یا زنانہٕ، یا بچہٕ یا زمینہٕ ترٲومُت چُھ، \n30. مگر تس میلہِ اتھ وقتس منز ہتھ گنہٕ، گرٕ تہٕ بٲے تہٕ بینہٕ تہٕ ماجہ تہٕ بچہٕ تہٕ زمینہٕ تہٕ ظلمہٕ سٍتـ̡ ۔ تہٕ ینہ وٲلِس دنیاہس مَنٛز ابدی زندگی۔ \n31.\\tمگر واریاہ {یُس} گۅڈنچہ لٹہِ آسن ٲخری آسن۔ تہٕ ٲخری گۅڈنچہ لٹہِ۔ \n32. تہٕ تِم ٲسۍ یروشلمس کُن گژھن واجنہِ وتہِ منز۔ تہٕ عیسیٰ مسیح گۆو تِمن برونہہ کُن، تہٕ تِم گٔیہِ حٲران۔ تہٕ یێلہِ تِم پَتہٕ پَتہٕ گٔیہ، تِم گٔیہِ کھوژان۔ تہٕ تٔمۍ رٔٹِتھ دُبارٕ باہ تہٕ ہیوٚتُن تِمن وَنُن زِ أمِس کیا سپدُن، \n33. {ونان}، وُچھِو أسۍ یروشلمس کُن نیران۔ تہٕ انسان سُند فرزند یِیہِ سردارین تہٕ کاتبن حوالہٕ کرنہٕ۔ تہٕ تِم دِن أمِس موتُک سزا تہٕ غیر قومن حوالہٕ۔ \n34.\\tتہٕ تِم کرِ أمِس ٹھٹھہٕ کٔرِتھ، تہٕ تھپھ دِن، تہٕ مارِن أمِس تہٕ تریمہِ دۅہہ گژھہِ سُہ دُبارٕ وُتھنہٕ۔ \n35.\\tتہٕ یعقوب تہٕ یوحنا یِم زبدی سٕندِ نیچوۍ چھِ أمِس نِش آمٕتۍ، وَنُن زِ آقا، أسۍ چھِ یژھان زِ ژٕ کٔرِو اسہِ خٲطرٕ یُس أسۍ یژھان چھِ۔ \n36.\\tتہٕ تٔمۍ ووٚن تِمَن زِ بہٕ کیا کٔرِو ژےٚ خٲطرٕ؟ \n37.\\tتِمو ووٚن أمِس زِ أسۍ بِہِتھ، اَکھ تُہٕندِس دٔچِھنہِ اتھس تہٕ بیٛاکھ کھوورِ اتھس پیٹھ، چانہِ عظمتس مَنٛز۔ \n38.\\tمگر حضرت عیسیٰ علیہ السلام ووٚن تِمن زِ ژیہ چھے نہٕ پتاہ زِ کیا چُھہ پرژھان: کیا تُہۍ ہیکو سُہ پیالہ چِھہ یُس بہٕ چیوان چُھس؟ تہٕ یُس بپتسمہ دِنہٕ آمُت چُھس سٍتـ̡ بپتسمہ دِنہٕ آمُت؟ \n39.\\tتہٕ تِمو ووٚن أمِس زِ أسۍ ہیکو کٔرِتھ۔ تہٕ حضرت عیسیٰ علیہ السلام ووٚن تِمَن زِ یُس بہٕ چُھس چُھس، یُس پیالہ چُھس چُھس۔ تہٕ یُس بپتسمہ دِنہٕ سٍتـ̡ بہٕ چُھس بپتسمہ دِنہٕ سٍتـ̡ تہٕ یێلہِ بپتسمہ دِنہٕ یُن: \n40.\\tمگر میٲنس دچھنہِ اتھس تہٕ کھوورِ اتھس پیٹھ بِہُن چُھہ نہٕ میون دِنہٕ خٲطرٕ۔ مگر {یہٕ گژھہِ تِمن دِنہٕ} یِمن ہٕندِ خٲطرٕ یہ تیار کرنہٕ آمُت۔ \n41.\\tتہٕ ییلہ دہن بوٗز، تِمو ہیوٚتُن جیمز تہٕ جانس سٍتـ̡ واریاہ ناراض۔ \n42.\\tمگر حضرت عیسیٰ علیہ السلام بُلووُن تِمن سٍتـ̡ تہٕ چُھہ تِمن پى۪ٹھـ̡\n43. مگر یُس تہِ آسہِ نہٕ تۅہہِ منز، یُس تہِ عظیم آسہِ، سُہ آسہِ تُہند وزیر۔ \n44. تہٕ یُس تہٕ یُس سارِوٕے کھۄتہٕ بٔڈ آسہِ، سُہ آسہِ سارِنٕے ہُند خادم۔ \n45. تکیازِ انسان سُند فرزند تہِ آو نہٕ خدمت کرنہٕ خٲطرٕ، بلکہ خدمت کرنہٕ خٲطرٕ، تہٕ واریاہن ہٕندِ خٲطرٕ پنٕنۍ زُو دِنہٕ خٲطرٕ۔ \n46. تہٕ تِم آیہِ یریحو کُن: تہٕ یێلہِ سُہ پَنٕنِس شٲگِرَن تہٕ وارِیاہَن لُکن سٍتـ̡ یریحو منزٕ نٮ۪بر درٛاو، تیمیئس سُند نیچو انہِ بِہتھ بِہتھ گُزاران ۔ \n47. تہٕ ییلہِ أمِس بوز زِ یہِ اوس عیسیٰ مسیح ناصریتُک ، تٔمۍ ہیوٚت کرٛٮ۪کھ دِنہٕ تہٕ وونُن، عیسیٰ مسیح، داؤد سُند نیچو، میانہِ پیٹھ رحم کر۔ \n48.\\tتہٕ واریاہو لوگُکھ أمِس حکم زِ سُہ گژھہِ خاموش روزُن، مگر سُہ وۆن زیادٕ روُن، {ژے} داؤد سُند نیچو، میانہِ پیٹھ رحم کرُن۔ \n49.\\tتہٕ عیسیٰ علیہ السلام کھڑا کھڑا تہٕ دِتُن أمِس بُلاونُک حُکُم۔ تہٕ تِم چھِ انہِ نفرس بلاوان تہٕ أمِس ونان زِ رژھرٕ، وۅتھٕ ووٚتھ؛ سُہ چُھ ژےٚ بلاوان۔ \n50. تہٕ سُہ ووت پَنُن پلو ترٛٲوِتھ تہٕ ووت عیسیٰ ہس نِش۔ \n51.\\tتہٕ حضرت عیسیٰ علیہ السلام دیُت جواب تہٕ وونُن، ژٕ کیا چُھس بہٕ ژے کٔرِتھ؟ انہِ نفرن ووٚن أمِس خداوند، یُتھ بہٕ ہێکہٕ گاش حٲصل کٔرِتھ۔ \n52.\\tتہٕ حضرت عیسیٰ علیہ السلام ووٚن أمِس پَنٕنـ̡ وَتہٕ پٲٹھـ̡ پى۪ٹھ۔ تێلہِ بێیہِ بێیہِ عیسیٰ سٕندِس وتہِ پى۪ٹھ۔ {بَنٲوِمُت...: یا بێیہِ تُہٕندِس وَتہِ پى۪ٹھ۔","1. تہٕ ییلہ تِم زیتون کِس پہاڑس پیٹھ بیت فیج تہٕ بیتھانی نِش وٲتۍ، سُہ سوزُن پَنٕنـ̡ زٕ شٲگِر، \n2.\\tتہٕ تِمن وَنُن زِ گامس مَنٛز گژھِو پانس خٕلاف۔ تہٕ یُتھ ژیہ اَتھ مَنٛز اژِو، وُچھِو اکھ کُلہٕ بٔنِتھ، یتھ پیٹھ نہٕ انسان بِہتھ آسہِ۔ أمِس یلہٕ تراوُن، تہٕ أنِو سُہ ۔ \n3. تہٕ اگر کانہہ انسان ژیہ ونان، تہٕ کیازِ چُھہ یہِ کران؟ تُہۍ ؤنِو زِ خداوند چُھ أمِس سٕنز ضرورت۔ تہٕ سُہ سوزِ سُہ سُہ یور ۔ \n4.\\tتہٕ تِمو گٔیہِ پننہِ وتہِ تہٕ وُچھِتھ وُچھِتھ دروازس سٍتۍ بٔنِتھ یُس دۅشوے وتہٕ رلان چھُ۔ تہٕ تِمو دِژ أمِس یلہٕ۔ \n5.\\tتہٕ یِمو منزٕ یِمو منزٕ کینہہ یِم اَتہِ کھڑا ٲسۍ، تۅہہ کیا چُھکھ کٔرِتھ کُنہِ \n6. تہٕ تِمو ووٚن تِمن یِتھٕ پٲٹھۍ حضرت عیسیٰ علیہ السلام حُکُم دِژمُت اوس، تہٕ تِمو دِژ تِمن یِمن تراون۔ \n7. تہٕ تِمو اوٚن عیسیٰ ہس نِش تہٕ لوٚگ أمِس پَنٕنۍ پَلَو۔ تہٕ سُہ بیوٹھ أمِس پیٹھ۔ \n8.\\tتہٕ واریاہ ٲسۍ پنٕنۍ پلو وتہِ وتہِ پھٔہلٲوِتھ: تہٕ باقیو ژٔٹِکھ کُلٮ۪ن ہٕنزِ لنجہِ تہٕ وتہِ کُلِس منز کٔرِتھ۔ \n9.\\tتہٕ یِم برونہہ کُن گٔیہِ، تہٕ یِمو پتہٕ یِمو پَتہٕ گٔیہِ، وَنُن ہُسنا۔ یُس خداوند سٕندِ ناوٕ سٍتـ̡ یِوان چُھہ سُہ بابرکت چُھ: \n10. سٲنِس مٲلِس داؤد سٕنزِ بادشٲہی مُبارکت، یُس خداوند سٕندِ ناوٕ سٍتـ̡ یێلہِ ہُسنا سٕندِس ناوس سٍتـ̡ یێلہِ ہُند دٲیرٕ چُھہ ۔ \n11. تہٕ عیسیٰ ژاو یروشلمس مَنٛز تہٕ مندرس مَنٛز، تہٕ ییلہ تٔمۍ سارِنٕے چیزن وُچھان تہٕ وُنہِ شام آو تہٕ سُہ دراو بہن ہٕندِس سٍتـ̡ بیتھنی کُن۔ \n12.\\tتہٕ پوٚت دۅہہ ییلہ تِم بیتھنی پیٹھٕ آیہ، أمِس اوس فاقہٕ گومُت: \n13.\\tتہ دوٗرِ اندۍ پکھۍ اکھ انجیر کُلِس وُچھِتھ آو سُہ وُچھِتھ یُس اَتھ منز کانہہ چیز لبنہٕ یِیہِ، تہٕ ییلہ سُہ اتھ نِش ووت، تٔمِس لوٚب نہٕ پنہٕ ؤتھرو علاوٕ کیٚنٛہہ تہِ۔ تکیازِ انجیر ہُند زمانہٕ اوس نہٕ وُنیُک۔ \n14.\\tتہٕ حضرت عیسیٰ علیہ السلام دیُت جواب تہٕ وونُن، یێمہِ سٍتـ̡ چُھہ نہٕ تُہٕندِس پھل کھٮ۪نہٕ پتہٕ ہمیشہٕ خٲطرٕ۔ تہٕ تٔمۍ سٕندٮ۪و شاگردو بوز {یہ}۔ \n15. تہٕ تِم آیہ یروشلمس مَنٛز، تہٕ حضرت عیسیٰ علیہ السلام ژاو مندرس مَنٛز، تہٕ ہیوٚتُن تِم کٔڑِتھ یِم مندرس مَنٛز کٕننہٕ تہٕ ہینہٕ وٲلۍ، تہٕ پٲنسہٕ بدلاون والٮ۪ن ہٕنزِ میزہٕ تہٕ کۅتر کٕننہٕ والٮ۪ن ہٕنزِ نشستہٕ الٹٲوِتھ ۔ \n16.\\tتہِ گژھہِ نہ کانہہ تہِ انسان مندرس منز کانہہ تہِ بانہٕ نِتھ۔ \n17.\\tتہٕ تٔمۍ ہیچھناوُن تِمن وونُن، کیا یہ چھُنہٕ لیکھنہٕ آمُت، میون گرٕ گژھہِ سارِنٕے قومن ہُند عبادت خانہٕ وننہٕ؟ مگر ژے بنوو یہ چورن ہُند گۅپھ۔ {سارِنٕے سٍتـ̡...: یا، سارنٕے قومن ہٕندِ خٲطرٕ دُعا خانہٕ}\n18.\\tتہٕ کاتبو تہٕ بٔڈۍ پادٕریو بوز تہٕ ژھانڈُکھ زِ تِم کِتھہٕ کٔنۍ ہیکن أمِس تباہ کٔرِتھ، تکیازِ تِم ٲسۍ أمِس کھوژان، تکیازِ سارِنٕے لوٗکھ ٲسۍ تٔمۍ سٕندِس نظریہٕ سٍتـ̡ حٲران گٔمٕتۍ۔ \n19. تہٕ ییلہ تہِ آو سُہ شہر نیبر۔ \n20.\\tتہٕ صُبحَس ییٚلہِ تِم اَکہِ کُلِس پٔکۍ، تِمو وُچھ انجیر کُلِس موٗلہٕ پٮ۪ٹھٕ ہۄکھمُت۔ \n21.\\tتہٕ پطرس یاد دِنہٕ خٲطرٕ بلاوان چُھہ أمِس ونان زِ آقا، وُچھِو انجیر کُلِس یُس ژے لعنتُک دُعا دِژمُت چھُ۔ \n22. تہٕ عیسیٰ مسیح چُھ تِمن جواب دِوان زِ خدایہِ سُند پژھ تھاوُن۔ {ہاو...: یا خدایہ سُند ایمان تھاوُن}\n23. یێلہِ بہٕ چُھس ژےٚ ونان زِ یُس تہِ یَتھ پہاڑس وَنُن چُھ، تێلہِ گژھہِ ژٔٹِتھ تہٕ سمندرس مَنٛز تراونہٕ یُن۔ تہٕ یێمہِ سٕندِس دِلس مَنٛز گژھہِ نہٕ شک کرنہٕ، بلکہ گژھہِ یقین زِ یُس سُہ وَنُن چُھ، تِم گژھن سپدِ۔ سُہ یُس تہِ وَنُن چُھ، سُہ گژھہِ سُہ تہِ میلہِ۔ \n24. تێمہِ کِنۍ چُھس بہٕ ژےٚ وَنُن، یێلہِ تہٕ یێلہِ تہِ میلہِ۔ \n25. تہٕ یێلہِ تہٕ یێلہِ تُہۍ دُعا کران ٲسِو، تێلہِ کٔرِو معاف، یێلہِ تہٕ تُہُند مول یُس آسمانس مَنٛز چُھ، تہٕ کرِ تُہٕندِس گناہ معاف۔ \n26. مگر یێلہِ نہٕ تُہُند مول یُس آسمانس مَنٛز چُھ، تُہٕندِس گناہ معافی دِیہِ۔ \n27. تہٕ تِم آیہ دُبارٕ یروشلمس کُن، تہٕ ییلہ سُہ مندرس مَنٛز پکان اوس، تٔمِس نِش آیہِ سردار پادٕر، کاتب تہٕ بزرگ، \n28.\\tتہٕ أمِس وَنُن، یِم کتھ کمہِ اِختِیارٕ سٍتـ̡ چُھہ تۅہہِ دِژمٕژ؟ تہٕ یِم کامہِ کرنہٕ خٲطرٕ کٔمۍ دِیُت تۅہہِ یہِ اِختِیار؟ \n29. تہٕ حضرت عیسیٰ علیہ السلام دیُت جواب تہٕ تِمن وونُن، بہٕ تہِ پرژھہٕ ژےٚ اکھ سوال، تہٕ مےٚ جواب دِیُن، تہٕ بہٕ وَنُن بہٕ کمہِ اِختِیارٕ سٍتـ̡ یِم کٲم کَرٕنـ̡ ۔ {سوال: یا، چیز}\n30.\\tیوحنا سُند بپتسمہ اوسا اسمانہٕ سٍتـ̡ یا انسانن سٍتـ̡ ؟ جَواب دِ. \n31.\\tتہٕ تِمو کٔر پانس سٍتـ̡ استدلال کٔرِتھ، یێلہِ أسـ̡ اسمانہٕ پى۪ٹھ۔ سُہ وَنُن زِ تێلہِ کیازِ کٔرِو نہٕ تٔمِس پى۪ٹھ۔ \n32.\\tمگر اگر أسۍ ونو انسانس متعلق۔ تِم ٲسۍ لُکن ہُند خوف تھاوان: سارِنٕے انسانو اوس یوحنا سُند گنزراونہٕ آمُت، زِ سُہ اوس پٔزۍ پٲٹھۍ پیغمبر۔ \n33. تہٕ تِمو دِژ جواب تہٕ وونُن عیسیٰ مسیحس زِ أسۍ ہیکو نہٕ ؤنِتھ۔ تہٕ حضرت عیسیٰ علیہ السلام چُھ تِمن جواب دِوان تہٕ بہٕ چُھس نہٕ ژےٚ وَنُن زِ بہٕ کمہِ اختیارس سٍتـ̡ یِم کٲم کران چھُس۔","1.\\tتہٕ ہیوٚتُن تِمن سٍتـ̡ تمثیلن سٍتـ̡ کتھ کرٕنـ̡ ۔ أکۍ {یقین} نفرن کٔر اکھ انگور باغ، تہٕ اتھ اندۍ پکھۍ اکھ باڑ تھووُن، تہٕ کھنُن {اکھ جاے} تہٕ بنووُن اکھ مینار تہٕ دِژن زمیندارن نِش تہٕ دِژُن أکِس دور مُلکس منز۔ \n2.\\tتہٕ یێمہِ موسمس سٍتـ̡ سوُز تٔمۍ کٔرِن زمیندارن نِش اکھ نوکر، یُتھ سُہ کٔرِن زٔمیٖن دارن نِش انگور ہٕندِس مٮ۪وُک مٮ۪وٕ حٲصِل کٔرِتھ۔ \n3.\\tتہٕ تِمو رٔٹِتھ تہٕ مار دِژُکھ تہٕ سوٗزُکھ خٲلی کُن۔ \n4.\\tتہٕ دُبارٕ سوٗز تِمن نِش بیاکھ نوکر۔ تہٕ تِمو لگٲوِکھ تِمَس کَلَس کَلَس پٲٹھۍ، تہٕ سوٗزُن شرمناک سٍتـ̡ دِنہٕ۔ \n5.\\tبییہِ سوز تمۍ بیاکھ اکھ ۔ تہٕ سُہ مارُن تہٕ باقٕے واریاہ مٲرِتھ۔ کینژَن مارُن تہٕ کینہہ مارُن۔ \n6.\\tاَمہِ کِنۍ اَکھ نیچو آسنہٕ کِنۍ، یُس تٔمۍ سُند محبوب اوس، تٔمۍ سُہ تہِ تِمن نِش تہِ وونُن زِ تِم کرَن میٲنِس نیچوِس احترام۔ \n7.\\tمگر تِمو زٔمیٖن دارو ووٚن پانَے منز، یہِ چُھ وٲرِث۔ یِمو أسۍ أمِس مارُن، تہٕ وَراثت گژھہِ سانہِ۔ \n8.\\tتہٕ تِمو نِش تہٕ مٲرِتھ تہٕ کٔرِکھ سُہ انگور منزٕ کٔڈِتھ۔ \n9. تَمہِ کِنۍ کیا کرِ انگورُک مالک؟ سُہ یِیہِ تہٕ کٔرِن زٔمیٖن دارن تباہ تہٕ دِیہِ باقیَن دِنہٕ۔ \n10. تہٕ کیا ژے یہ صحیفہٕ پٔرِتھ چُھہ نہٕ۔ سُہ کُن یُس معمارو رد کورمُت چُھ، سُہ چُھ کونہٕ سُند کلہٕ بنیومُت: \n11.\\tیہ ٲس خداوند سنز کٲم تہٕ یہ چھیہ سانہِ نظرِ منز حیرت انگیز؟ \n12.\\tتہٕ تِمو کٔر أمِس تھپھ کرنٕچ کوشش، مگر لُکن ہٕندِس خوفَس سٍتـ̡ تکیازِ تِمن ٲس پتاہ زِ تٔمۍ ٲس تِمن خلاف تمثیل بولمٕژ، تہٕ تِمو ترٲوِتھ گٔیہِ أمِس وتہٕ۔ \n13.\\tتہٕ تِمو سوزان أمِس نِش فریسی تہٕ ہیرودین ہٕندِس کُنہِ سٍتـ̡ تٔمِس رٔٹِتھ رٔٹِتھ ۔ \n14.\\tتہٕ ییلہ تِم آیہ، تِم چھِ أمِس ونان زِ أسۍ چھِو پٔزۍ پٲٹھۍ، تہٕ چُھکھ نہٕ کٲنسہ تہِ انسانس پرواہ کران، کیازِ تہٕ تہٕ چُھہ نہٕ انسانس سٍتـ̡ خدایہِ سٕنز وتھ ہیچھناوٕنـ̡ حقیقتس سٍتـ̡ ہیچھناوان چُھہ: کیا قیصرس خراج دِنہٕ چُھہ حلال کِنہٕ نہٕ؟ \n15.\\tأسۍ دِنہٕ کِنہٕ دِنہٕ نہٕ؟ مگر تِمن ہٕنزِ منافقت زٲنِتھ ووٚن تِمن زِ ژیہ کیازِ چُھکھ میہ لالچ؟ مے أنِو اکھ پونسہٕ، یُتھ بہٕ وُچھِتھ {یہ}۔ {پونسہٕ: سانہِ پونسہٕ ہُند قدر ستھ پینس نصف پونسہ}\n16.\\tتہٕ تِمو أنۍ {یہ}۔ تہٕ سُہ چُھ تِمن ونان زِ یہِ تصویر تہٕ تحریر کٔمۍ سٕندِس چُھ؟ تہٕ تِمو ووٚن أمِس سیزر سُند۔ \n17.\\tتہٕ حضرت عیسیٰ علیہ السلام ووٚن تِمن جواب دِتھ یِم چیز قیصرس تہٕ خدایہ سٕندِ سٍتـ̡ دِیِو تِم چیز یِم خدایہِ سٕندِس سٍتـ̡ چھِ۔ تہٕ تِمو گٔیہِ أمِس سٍتـ̡ حٲران ۔ \n18.\\tتیلہِ آو أمِس نِش صدوقی یُس ونان چھُ زِ قیامتُک کانہہ تہِ چُھہ نہٕ۔ تہٕ تِمو پرژھ أمِس ، \n19.\\tماسٹر موسیٰ ین لیوکھ اسہِ زِ اگر کٲنسہِ مردس بٲے مرِ، تہٕ پننہِ زنانہِ تراوِ تہٕ کانہہ شُر تراوُن، تٔمۍ سُند بٲے گژھہِ پننہِ زنانہِ نِش تہٕ پننِس بٲیِس سٍتـ̡ بیول دِنہٕ۔ \n20.\\tوۅنۍ ٲسۍ ستھ بٲے: تہٕ گۅڈنِچ خانٛدارِنۍ رٔٹِتھ تہٕ مرنہٕ سٍتـ̡ تروو نہٕ کانہہ بیٲل۔ \n21.\\tتہٕ دۆیمِس نِش نِش تہٕ مٔرِتھ تہٕ تٔمِس تروو نہٕ کانہہ بیٲل، تہٕ تریم تہِ۔ \n22.\\tتہٕ سَتَن ٲس سۅ تہٕ ترووُن نہٕ کانہہ بیٲل: سارِوٕے کھۄتہٕ ٲخٕر زنانہٕ تہِ مٔرۍ۔ \n23.\\tقیامتس مَنٛز ییلہ تم وۅتھنہٕ یِن، سۅ کٔمۍ سٕنزِ زنانہٕ آسہِ؟ تکیازِ ستن آسہِ أمِس خانٛدارِ۔ \n24.\\tتہٕ حضرت عیسیٰ علیہ السلام ووٚن تِمن جواب دِتھ زِ تێلہِ چُھہ نہٕ تۅہہ غلطی کران، تکیازِ تۅہہِ چُھہ نہٕ صحیفہٕ تہٕ خدایہ سٕندِس طاقتس سٍتـ̡ زانان؟ \n25. یێلہِ یێلہِ تِم مُردٕ پى۪ٹھہٕ بێیہِ، تِم چِھ نہٕ خاندر کٔرِتھ، تہٕ نہٕ چِھہ خاندر کرنہٕ یِوان۔ بٔلکہِ چِھ فرشتن ہٕندۍ پٲٹھۍ، یُس جنتس مَنٛز چُھ۔ \n26. تہٕ یێلہِ چُھہ تِم وُتھٕ وُتھ: کیا ژے چُھہ نہٕ موسیٰ سٕنزِ کتابہِ مَنٛز پٔرِمُت، کِتھہ پٲٹھـ̡ چُھہ خداین أمِس سٍتـ̡ کتھ کٔرِتھ زِ بہٕ چُھس ابراہیم سُند خدا، تہٕ اسحاق سُند خدا، تہٕ یعقوب سُند خدا۔ \n27. سُہ چُھ نہٕ مُردن ہُند خدا، بٔلکہِ چُھہ زندٕ سُند خدا، تێمہِ کِنۍ چُھہ تۅہہ واریاہ غلطی کران۔ \n28.\\tتہٕ اکھ کاتب آو تہٕ تِمن ہٕندِس اِکہٕ وٹہٕ استدلال بوزِتھ تہٕ یہ وُچھِتھ زِ تٔمۍ چُھ تِمن اصل جواب دِژمُت، پرژھُن، سارِنٕے سارِنٕے ہُند گۄڈنیُک حکم کُس چُھ؟ \n29. تہٕ حضرت عیسیٰ علیہ السلام دیُت أمِس جواب، سارِوٕے حُکمَن مَنٛز گۄڈنیُک {چُھ}، بوزو، اے اسرٲیل؛ خداوند سون خدا چُھ اکھ خدا: \n30. تہٕ ژے کرو خداوند پنُن خدایہ پنہٕ نِس پوٗرٕ دِلہٕ سٍتـ̡ تہٕ پنہٕ نـ̡ سٲرۍسٕے دِلہٕ سٍتـ̡ تہٕ پنہٕ نـ̡ سارِوٕے دِلہٕ سٍتـ̡ تہٕ پنہٕ نـ̡ سارِوٕے طاقتہٕ سٍتـ̡ محبت کرُن: یہِ چُھہ گۄڈنیُک حُکم۔ \n31.\\tدۆیِم {یعنی} یِتھٕ پٲٹھۍ، ژے کٔرِو پننِس ہمساین پانس پٲٹھۍ۔ یِمو کھۅتہٕ بٔڈ کانہہ تہِ حُکُم چھُنہٕ۔ \n32.\\tتہٕ کاتب ووٚن أمِس، خٲر، آقا، ژے چُھہ پٔز وَنُن، کیازِ چُھ اکھ خدا۔ تہٕ أمِس سٍتـ̡ چُھہ نہٕ کانہہ تہِ: \n33.\\tتہٕ أمِس سٲرۍسٕے دِلہٕ سٍتـ̡ تہٕ سٲرۍسٕے روحہٕ سٍتـ̡ تہٕ سارِوٕے طاقتہٕ سٍتـ̡ محبت کرُن، تہٕ پننِس ہمساین سٍتـ̡ پانس سٍتـ̡ محبت کرُن، سارِوٕے سٍتـ̡ محبت کرُن چُھہ سارِوٕے سٍتـ̡ \n34. تہٕ یێلہِ حضرت عیسیٰ علیہ السلام وُچھ زِ تٔمِس چُھہ ہوشیاری سان جواب دِژمُت، تٔمِس وۆنُن تٔمِس زِ تہٕ چُھہ نہٕ خدایہِ سٕنزِ بادشٲہی نِش دور۔ تہٕ اَمہِ پَتہٕ ہیوٚک نہٕ کٲنسہ تہِ انسان أمِس {کانہہ تہِ سوال} پرژھنٕچ ہمت کٔرِتھ۔ \n35.\\tتہٕ حضرت عیسیٰ علیہ السلام دیُت جواب تہٕ وونُن، ییلہ سُہ ہیکلس مَنٛز پرناوان اوس، کاتب کِتھہ کٔنۍ چُھ ونان زِ مسیح چُھ داؤد سُند نیٚچُو؟ \n36.\\tداؤد سٍتـ̡ وۆنُن پانہٕ روح القدس سٍتـ̡ تہٕ خداوند چُھہ میٲنِس آغس پیٹھ بِہتھ یوتام نہٕ بہٕ چانہِ دُشمن پنُن کھۅر بَناوُن۔ \n37. تَمہِ کِنۍ چُھ داؤد پانَے أمِس خداوند وَنان۔ تہٕ سُہ کتہِ چُھ تٔمِس نیچو چُھ؟ تہٕ عام لوٗکو بوز أمِس خوشی سان۔ \n38.\\tتہٕ تٔمۍ ووٚن تِمن پننِس عٔقیٖدس مَنٛز، یِم زیٖٹھۍ پلو لاگُن پسند کران چھِ، تہٕ بازرَن مَنٛز سلام کرُن پسند کران چھِ، \n39. تہٕ عبادتن مَنٛز اہم نشستہٕ، تہٕ دعوتن مَنٛز پیٹھمہِ کمرہٕ: \n40.\\tیُس بیواہ ہٕندِس گرس کھٮ۪وان چُھ، تہٕ بہانہ کٔرِتھ چھِ زیٹھۍ دُعا دُعا کران: یِمن ہُند دُعا میلہِ زیادٕ عذاب۔ \n41.\\tتہٕ حضرت عیسیٰ علیہ السلام بیوٹھ خزانس مَنٛز، تہٕ وُچھُن زِ لوکو کِتھہ کٔنۍ چھِ خزانہٕ مَنٛز پٲنسہٕ تراوان: تہٕ واریاہ امیر ٲسۍ۔ {پٲنسہٕ: پیتلُک اکھ ٹُکر}\n42.\\tتہٕ اَکھ بیچارہ بیواہ آیہ، تہٕ تٔمۍ ترٛٲوۍ زٕ مِٹ، یُس اکھ فارتھنگ بناوان چھُ۔ {mites: یہ چُھ تمہِ پیتلٕکۍ پونسہٕ ہُند سٔتِم حصہٕ}\n43. تہٕ تٔمۍ بُلوو پننین شاگردن تہٕ تِمن وَنُن زِ بہٕ چُھس ژےٚ وَنُن زِ یہِ بیواہ بیواہ چُھ تِمو سارِوٕے کھۄتہٕ زیادٕ دِژمُت یِمو خزانس مَنٛز ترٛٲومٕژ چھِ: \n44.\\tسارِنٕے {تِم} کٔر تِمن ہٕنزِ کثرت سٍتـ̡ دِنہٕ۔ مگر تٔمۍ کٔر پننہِ محتاجہ سٍتـ̡ سٍتـ�","1. تہٕ ییلہ سُہ مندرٕ منزٕ نیبر نیران، تٔمۍ سُند اکھ شٲگِر چُھ أمِس وَنُن، مالک، وُچھِو کَمہِ قٕسمٕکۍ کٔنہِ تہٕ کمہٕ عمارتہٕ چھِ۔ \n2. تہٕ حضرت عیسیٰ علیہ السلام ووٚن أمِس جواب دِتھ زِ ژے چھُکھ یِم بٔڈ عمارتہٕ وچھان؟ اَکھ کٔنہِ گژھِ نہٕ أکِس کٔنہِ پٲٹھۍ، یُس نہٕ یِنہٕ والہِ پٲٹھۍ۔ \n3. تہٕ ییلہ سُہ زیتون کِس پہاڑس پیٹھ بِہتھ مندرس خلاف بِہتھ، پطرس تہٕ جیمز تہٕ یوحنا تہٕ اندریو پرژھ أمِس ذٲتی پٲٹھۍ، \n4.\\tاسہِ ونو یِم چیز کر سپدِ؟ تہٕ یِم سارِنٕے چیٖز پوٗرٕ سپدِن تیلہِ کیا آسہِ نشانہٕ؟ \n5.\\tتہٕ حضرت عیسیٰ علیہ السلام ہیوٚت تِمن جواب دِتھ وَنُن زِ یِمن ہُند جواب دِنہٕ یِنہٕ سٍتـ̡ کُنہِ تہِ انسانس دھوکہٕ دِنہٕ۔ \n6. تِکیازِ واریاہ یِن میانہِ ناوٕ سٍتـ̡ یِن، بہٕ چُھس {مسیح}؛ تہٕ کرٕ واریہن لوٗکن دھوکہٕ۔ \n7. تہٕ ییلہ جنگن تہٕ جنگن ہٕنز افواہ بوزِو، تیٚلہِ گژھِو نہٕ پریشان گژھُن: کیازِ {یِتھٕ چیز} گژھہِ آسنٕچ ضرورت۔ مگر انجام {s} گژھہِ نہٕ وُنیُک {آسُن}۔ \n8.\\tقومس خلاف گژھہِ قومس خلاف کھڑا تہ سلطنت گژھہِ سلطنتس خلاف کھڑا تہ مختلف جاین گژھہِ زلزلہ، تہ قحط تہٕ پریشانی: یِم چھہِ غمن ہُند آغاز۔ {غم: اصلی لفظس منز چھہ \"زنانہِ ہٕندِس مصیبت سٍتـ̡ دَگ\"}\n9.\\tمگر پانس سٍتـ̡ ہوشیار کرُن، تکیازِ تِم گژھن تۅہہِ مجلسن تام واتناوٕنۍ۔ تہٕ یہودی عبادت خانن مَنٛز یِن تم مار دِنہٕ۔ تہٕ یِم یِن میانہِ خٲطرٕ حکمرانن تہٕ بادشاہن برونہہ کُن اننہٕ، تِمن خلاف گوٲہی دِنہٕ۔ \n10. تہٕ انجیل گژھہِ سارنٕے قومن مَنٛز شایع کرنہٕ یُن۔ \n11. مگر ییلہ تۅہہِ رہنمٲیی کرِ، تہٕ تۅہہِ رٲچھ کرن، تہٕ یێلہِ تہِ کرو نہٕ تۅہہِ کتھ کرنہٕ، تێلہِ کرو نہٕ گۅڈے سوچ، مگر یُس تہِ تۅہہِ اتھ ساعتس منز دِنہٕ ییہِ، تۅہہِ کتھ کرُن، تکیازِ تۅہہ چُھہ نہٕ کتھ کران بلکہ روح القدس۔ \n12.\\tوۅنۍ گژھہِ بٲے بٲے سٍتـ̡ مارُن، تہٕ مٲلِس نیچوِس سٍتـ̡ دِنہٕ۔ تہٕ بچہٕ گژھن پننِس مٲلِس ماجہ سٍتـ̡ کھڑا تہٕ یِم مارنہٕ یِن۔ \n13.\\tتہٕ یُس میانہِ ناوٕ خٲطرٕ سارِنٕے انسانس سٍتـ̡ نفرت، مگر یُس ٲخرس تام زندٕ روزِ، سُہ گژھہِ نجات دِنہٕ۔ \n14.\\tمگر ییلہ تم ویرانی ہٕنز نفرت وُچھِو، یُس دانیال پیغمبرن کُن وننہ آمُت چھُ، یێلہِ نہٕ یہ گژھہِ نہٕ کھڑا گژھُن، (یُس پران چُھ، تێلہِ گژھن یہوداہس مَنٛز موجود تِم پہاڑن کُن ژلُن: \n15.\\tیُس مکانس پیٹھ آسہِ سُہ گژھہِ نہ گرس منز بۄن تہٕ نہ اژُن تہٕ نہ گژھہِ پننہِ گرٕ منزٕ کانہہ چیز نِنہٕ۔ \n16. تہٕ یُس کھاہس منز آسہِ سُہ گژھہِ نہ پَنُن پلو تُلنہٕ خٲطرٕ دُبارٕ پھیُرُن۔ \n17.\\tمگر یِمن دۅہن شُرِ ہٕندِس سٍتـ̡ تہٕ یِمن دۅہن دِنہٕ وٲلِس سٍتـ̡ افسوس! \n18.\\tتہٕ دُعا کٔرِو زِ تُہند پرواز گژھہِ نہٕ وندس مَنٛز۔ \n19. تِمن دۅہن آسہِ مصیبت، یُس نہٕ تخلیقہٕ کِس آغازس پیٹھٕ یُس خداین از تام تخلیق کورمُت اوس، تہٕ نہ آسہِ تہٕ آسہِ۔ \n20. تہٕ یێمہِ سٍتـ̡ خداوند یِم دۅہ کم کٔرۍمٕتۍ، تێلہِ گژھہِ نہٕ کانہہ تہِ ماز بچاونہٕ یُن، مگر ژارنہٕ آمٕژ سٕندِ خٲطرٕ، یُس تٔمۍ ژٲرمُت چُھ، تٔمۍ کٔر دۅہ ژھوٚٹ۔ \n21. تہٕ پَتہٕ یێلہِ کانٛہہ تہِ انسان وَنُن چُھ، یێلہِ چُھ مسیح {چُھ}؛ یا، لو، {سُہ چُھ} تتہِ؛ {أمِس} پژھ نہٕ کٔرِو: \n22.\\tکیازِ غلط مسیح تہٕ اپُز پیغمبر گژھن وۅتھان تہٕ گژھن نشانہٕ تہٕ عجائبات ہاونہٕ، یێلہِ تہِ ژارنہٕ آمُت آسہِ۔ \n23.\\tمگر دھیان تھاوُن: وُچھِو مے ژے سارِنٕے چیزن ہٕنز پیشن گویی کٔرمٕژ۔ \n24. مگر تِمن دۅہن یێمہِ مصیبت پَتہٕ آفتاب گژھہِ انہِ گوٚٹ تہٕ زونہِ دِیہِ نہٕ تس گاش، \n25. تہٕ آسمانٕکۍ تارکھ پیوٚن تہٕ آسمانس مَنٛز موجود طاقتہٕ گژھن ہلاونہٕ۔ \n26. تہٕ پَتہٕ وُچھن تِم اِنسان سُند نیٚچُو یُس اُبرن مَنٛز بٔڈۍ طاقتہٕ تہٕ جلال سان یِوان چھُ۔ \n27. تہٕ پَتہٕ سُہ سُہ پَنٕنـ̡ فرشتہٕ سُہ پَنٕنـ̡ فرشتہٕ سٍتـ̡ ژۄن ہواو سٍتـ̡ پَنٕنـ̡ ژۄن \n28.\\tوۅنۍ ہیچھِو انجیر کُلِچ اکھ تمثیل۔ ییلہ تٔمۍ سٕنزِ لنجہِ وُنہِ تہِ نرم آسہِ، تہٕ پنہٕ ؤتھٕر کڈِتھ چھِ، ژے چھُ پتاہ زِ رٮ۪تہٕ کال چھُ نزدیک: \n29.\\tیِتھے پٲٹھـ̡ ییلہ یِم چیز سپدان وُچھِو، زانِو زِ یہِ چُھہ نزدیک، {حتی} دروازس پیٹھ۔ \n30. بہٕ چُھس ژےٚ ونان زِ یِم سٲری چیز سپدِن توٚت تام گژھِ نہٕ یہِ نسل گزرِ۔ \n31. اسمانس تہٕ زمینہٕ گژھن ژٔلِتھ مگر میٲنۍ کلام گژھن نہٕ ختم۔ \n32. مگر تمہِ دۅہہٕ تہٕ {تَمہِ} وقتس مُتلق چُھہ نہٕ کانہہ تہِ انسانس زانان، نہٕ فرشتن یُس اسمانس مَنٛز چُھ، تہٕ نہ چُھہ فرزند، بلکہ باپ۔ \n33.\\tتوجہ کرُن، وُچھِو تہٕ دُعا کرُن، تکیازِ ژیہ چھُنہٕ پتاہ زِ وق کر چُھ۔ \n34.\\t{تکیازِ انسان سُند فرزند} چُھ یُس انسان سُند دور سفر کٔرِتھ، یُس پَنُن گَرٕ نیران چُھ، تہٕ دِتُن پننین نوکرَن تہٕ پرٮ۪تھ أکِس انسانس پنٕنۍ کامہِ ہُند اِختِیار دِیُت، تہٕ دِتُن پورٹرس نظر تھاونُک حُکُم۔ \n35.\\tتێلہِ وچھو: تۅہہ چھیہ نہ پتاہ زِ گرُک مٲلک کٔر یِوان، شامس منز، نصف رٲژ یا کۅکرس پیٹھ، یا صبحس ییلہ یِوان: \n36.\\tاچانک یِنہٕ سُہ گژھہِ تۅہہِ شوٚنگِتھ وُچھان۔ \n37.\\tتہٕ یُس بہٕ ژے ونان چھُس بہٕ سارِنٕے وَنُن وَنان۔","1.\\tدۅن دۅہن پَتہٕ اوس فسح تہٕ خمیر روٚس روٹی ہُند تہٕ بٔڈۍ پادٕرۍ تہٕ کاتب ژھانڈان زِ تِم کِتھہ کٔنۍ ہیکن أمِس ہنرِ سٍتـ̡ نِتھ، تہٕ دِژن أمِس مارنہٕ۔ \n2.\\tمگر تِمو ووٚن نہٕ تہٕ عید دۅہہ، یُس نہ لُکن ہُند ہنگامہ گژھہِ۔ \n3.\\tتہٕ بیتھنی منز شمعون کوڑھ سٕندِس گرس منز، ییلہ سُہ مازس پیٹھ بِہتھ اوس، اَکھ زنانہٕ آیہِ سُہ سٮ۪ٹھاہ قیمتی مرہم ہُند ڈبہٕ اوس۔ تہٕ تٔمۍ کٔر ڈبہٕ بریک، تہٕ ترووُن تٔمِس کلس پیٹھ۔ {سپِکینارڈ: یا، خالص نارد، یا، مائع نارد}\n4.\\tتہِ ٲسۍ کینہہ یمن پانس اندر شرارت تہ وونُن زِ یہ مرہم کیازِ آو بنیوو؟ \n5.\\tتکیازِ یہ آسہ ہا تریہ ہتھ پینس کھۅتہ زیادہ کٕننہٕ آمُت، تہٕ غریبن دِنہٕ آمُت۔ تہٕ تِمو کٔر أمِس خٕلاف گڑبڑ۔ \n6. تہٕ عیسیٰ علیہ السلام ووٚن، أمِس تراوُن کُنہِ۔ تٔمِس کیازِ چُھہ تٔمِس تنگ کٔرِتھ؟ تٔمۍ کٔر میہ سٍتـ̡ رٔژ کامہِ۔ \n7. تِکیازِ چُھہ غریبَن ہمیشہٕ پانس سٍتـ̡ روزان، تہٕ ییلہ تہِ تہٕ یێلہِ تہِ یێلہِ تہِ تِمن نیکی کٔرِتھ، مگر میہ چُھہ نہٕ ہمیشہٕ۔ \n8.\\tتٔمۍ کٔر یُس سُہ ہیوٚک کٔرِتھ: سۅ چھے برونہہ کُن آمٕژ میانہِ جِسمس دفن کرنہٕ خٲطرٕ۔ \n9. یێلہِ تہِ چُھس ژے ونان زِ یێلہِ تہِ یێمہِ سٍتـ̡ یہِ انجیل سٲرۍسٕے دُنیاہس مَنٛز پراونہٕ ییہِ، {یہِ} یُس تٔمۍ سٕندِس یادگارس مۅکھٕ وننہٕ ییہِ۔ \n10. تہٕ یہوداہ اسکریوت، بہو منزٕ اکھ، گۆو سردار پادٕرین نِش، تِمن نِش دھوکہ دِنہٕ خٲطرٕ۔ \n11.\\tتہٕ ییلہ تِمو بوٗز، تِمو گٔیہِ خۄش، تہٕ کوٚرُکھ أمِس پٲنسہٕ دِنُک وعدٕ۔ تہٕ تٔمۍ ژھانڈ زِ سُہ کِتھ کٔنۍ کرِ أمِس دھوکہٕ۔ \n12. تہٕ گۅڈنِکہِ دۅہہٕ ییلہ تِمو فسح مٲرِتھ، تٔمۍ سٕندٮ۪و شٲگِرِو أمِس ووٚن، ژٕ کتہِ گژھِو أسۍ گژھِتھ تہٕ یُتھ ژے فسح کھٮ۪نہٕ خٲطرٕ تیار کٔرِتھ؟ {مٲرِتھ: یا قربان کرنہٕ}\n13. تہٕ سُہ چُھ پَنٕنـ̡ زٕ شٲگِرِ سوٗزِتھ تہٕ تِمن وَنُن چُھہ شہرس مَنٛز، تہٕ تتہِ گژھہِ تُہٕندِس أکِس شخٕص سٍتـ̡ آبہٕ ہُند جَگ ہٮ۪تھ، أمِس پٔکِو۔ \n14. تہٕ یێتہِ تہِ گژھہِ، یێلہِ تہِ گژھہِ گَرٕ کِس نیک شخصس وَنُن، آقا چُھ ونان زِ مہمان خانہٕ کتہِ چُھہ، ییتہِ بہٕ پننین شاگردن سٍتـ̡ فسح کھٮ۪یہِ؟ \n15.\\tتہٕ سُہ ہٲوِو تۅہہِ اکھ بوٚڈ پیٹھمہِ کمرہ یُس تیار آسہِ، تتہِ کرو اسہِ خٲطرٕ تیار۔ \n16.\\tتہٕ تٔمۍ سٕندِ شٲگِر دراو تہٕ شہرس مَنٛز، تہٕ وُچھُکھ یِتھٕ پٲٹھۍ تٔمۍ تِمن وَننہٕ آمُت اوس، تہٕ تِمو کٔر فسح تیار۔ \n17. تہٕ شامس چُھ سُہ بہن ہیتھ یوان۔ \n18.\\tتہٕ یێلہِ تِم بِہتھ کھٮ۪وان تہٕ حضرت عیسیٰ علیہ السلام وۆن، یێلہِ بہٕ چُھس ژے ونان زِ یُس میہ سٍتـ̡ کھٮ۪وان چُھ، سُہ کرِ میہ دھوکہٕ۔ \n19.\\tتہٕ ہیوٚتُن غمگسار تہٕ أمِس وَنُن اَکہٕ اَکہٕ پٲٹھۍ، {کیا یہ} بہٕ چھُس؟ تہٕ بیٛاکھ {ووٚنُن، کیا یہِ چھُس} بہٕ چھُس؟ \n20.\\tتہٕ تٔمۍ دیُت جواب تہٕ وونُن تِمن {یہ} چُھہ بہو منزٕ اکھ، یُس میہ سٍتـ̡ ڈِشس منز ڈوبان۔ \n21.\\tانسان سُند فرزند چُھ پٔزۍ پٲٹھـ̡ نیران، یُتھ زن أمِس متعلق لیکھنہٕ آمُت چُھ، مگر تٔمِس انسانس ہٕندِس سٍتـ̡ چُھہ افسوس یٔمِس سٍتـ̡ انسان سُند فرزند دھوکہ دِنہٕ آمُت چُھ! تٔمِس انسانس سٍتـ̡ چُھ نہٕ زانہہ زینہٕ آمُت۔ \n22. تہٕ یێلہِ تِمو کھٮ۪وان چُھ، حضرت عیسیٰ علیہ السلام نِش روٹی تہٕ برکت دِژٕن، تہٕ دِژُن تِمن دِژُن تہٕ وونُن، نِیُن، کھیوٚن، یێلہِ چُھ میٲنۍ جسم۔ \n23.\\tتہٕ تٔمۍ روٚٹ پیالہ تہٕ ییلہ تٔمۍ شُکر ادا کوٚر، تٔمۍ دِژ تِمن تہٕ تِمو سارِوٕے پیالہ چُھ۔ \n24. تہٕ تٔمۍ ووٚن تِمَن زِ یہِ چُھ میٲنۍ نٔوِس عہد نامُک خون، یُس واریاہن لوٗکن ہٕندِ خٲطرٕ بہاونہٕ چُھ یِوان۔ \n25. بہٕ چُھس ژے ونان زِ بہٕ چُھس نہٕ تتھ دۅہس تام یُس بہٕ خدایہ سٕندِس بادشٲہی مَنٛز نوِ نوِ چیٚو۔ \n26. تہٕ ییلہ تمو اکھ حمد گیو، تم گٔیہٕ زیتون کِس پہاڑس منٛز۔ {حمد: یا، زبور}\n27. عیسیٰ مسیح چُھ تِمن وَنُن، یێلہِ رٲژ میانہِ مۅکھہٕ گٔژھِو تُہۍ سارِنٕے ناراض گٔژھِو، تِکیازِ یہِ چُھہ لیکھنہٕ آمُت، بہٕ کٔرِس پٔرِتھ تہٕ کٔرِتھ کٔرِتھ ژٔٹِتھ ۔ {ناراض گٔژھِتھ: یا، سکینڈل، یا، ٹھوکر کھسنہٕ}\n28. مگر تمہ پتہ گۆو میہ زندہ، بہٕ گژھہِ ژے برونہہ کنہِ گلیل منز۔ \n29.\\tمگر پطرس ووٚن أمِس زِ یێلہِ سارِنٕے گٔژھ ناراض گٔژھِن، توتہِ گژھہِ نہٕ بہٕ نہٕ۔ \n30.\\tتہٕ عیسیٰ علیہ السلام چُھہ تس ونان زِ بہٕ چُھس ژے ونان زِ از رٲژ تہِ کۅکر کۅکرِ دۅیہ لٹہِ کۅکرِ برونہہ کُن ژے تریہ لٹہِ انکار کرُن۔ \n31.\\tمگر تٔمۍ کٔر زیادٕ زورٕ سان کتھ زِ اگر بہٕ ژے سٍتۍ مرُن، بہٕ کٔرٕ نہٕ ژےٚ کُنہِ تہِ پٲٹھۍ انکار۔ یِتھے پٲٹھۍ ووٚن تِمو سارِوٕے تہِ۔ \n32.\\tتہٕ تِم وٲتۍ أکِس جایہِ یتھ گتسمنی ناو اوس، تہٕ سُہ چُھ پننین شاگردن ونان زِ یێلہِ بہٕ بِہِتھ یێلہِ بہٕ دُعا کٔرِ۔ \n33.\\tتہٕ سُہ چُھ پطرس تہٕ جیمز تہٕ یوحنا پانس سٍتـ̡ نِتھ، تہٕ ہیوٚتُن حٲران تہٕ سٮ۪ٹھاہ گۄب۔ \n34. تہٕ چُھ تِمن وَنُن، میون روح چُھ مرنس تام سٮ۪ٹھاہ غمگسار گومُت: یتہِ رٔٹِو تہٕ وُچھو۔ \n35.\\tتہٕ سُہ پیوٚو رژھ کھنڈ برونہہ کُن، تہٕ پیوٚو زمینس پیٹھ، تہٕ دُعا کٔرُن زِ اگر یہ ممکن آسہِ، تس نِش گژھہِ وقت گزرُن۔ \n36. تہٕ تٔمۍ ووٚن، ابا، بابا، سٲری چیز چُھہ ژے خٲطرٕ ممکن۔ یہ پیالہ نِش نِن: بہٕ کیا چُھس نہٕ یژھان، مگر ژٕ یُس تہٕ چُھہ یژھان۔ \n37. تہٕ سُہ چُھ یِوان، تہٕ چُھہ تِمن شوٚنگِتھ وُچھان، تہٕ چُھہ پطرس، شمعن، ژٕ چُھکھ شوٚنگِتھ؟ کیا ژٕ ہیوٚک نہٕ اکھ گھنٹہٕ وُچھِتھ؟ \n38.\\tوُچھِو تہٕ دُعا کٔرِو، یێلہِ گژھہِ فتنس مَنٛز دٲخل گٔژھِو۔ روح چُھ پٔزۍ پٲٹھـ̡ تیار، مگر ماز {چُھ} کمزور۔ \n39.\\tتہٕ دُبارٕ گۆو سُہ دُعا تہٕ دُعا کٔرِن یۅہے لفظ۔ \n40.\\tتہٕ ییلہ سُہ واپس آو، تٔمۍ وُچھ تِم بییہ شوٚنگتھ، (تکیازِ تِمن ہٕنزِ أچھ ٲس گٔبۍ،) تہٕ نہ اوس تِمن کیا جواب دِنہٕ۔ \n41. تہٕ سُہ چُھ تریمہِ لٹہِ یِوان، تہٕ تِمن وَنُن چُھ، شوٚنگِتھ تہٕ آرام کرُن: یہِ چُھ کٲفی، وقت آو آمُت۔ وُچھِو انسان سُند فرزند گۅنہگارن ہٕندِس اتھس منز دھوکہٕ دِنہٕ۔ \n42.\\tتھوٚد تھوٚد، اسہِ گژھہِ نیرُن۔ یُس میہ دھوکہ دِوان چُھ، سُہ چُھ اتھس منز۔ \n43.\\tتہٕ یێلہِ سُہ وُنہِ تہِ کتھ کٔرِتھ، یہوداہ آو بہو منزٕ اکھ، تہٕ أمِس سٍتـ̡ چُھ بٔڈۍ پادٕرَن تہٕ کاتبَن تہٕ بزرگن ہٕندِس سٍتـ̡ تلوار تہٕ لٔٹھۍ ہیتھ واریاہ بٔڈِ۔ \n44.\\tتہٕ یٔمۍ أمِس دھوکھہٕ دِژ، تٔمِس اوس تِمن اکھ نشانہٕ دِژمُت، یُس بہٕ بوسہ دِیہِ، سُہ چُھ سُہ ۔ أمِس نِش نِن، تہٕ نِش نِنہٕ۔ \n45.\\tتہٕ یُتھ سُہ آو سیوٚد أمِس نِش تہٕ وَنُن مالک، مالک۔ تہٕ دِتُن أمِس بوس۔ \n46.\\tتہٕ تِمو تھوو أمِس پیٹھ اتھہٕ تہٕ رٔٹِتھ رٔٹِو۔ \n47.\\tتہٕ یُس اَکہِ نِش کھڑا اوس، تٔمِس کٔر تلوار تہٕ لوٚگُن أکِس پادٕرۍ سٕندِس نوکرس تہٕ ژٹُن تٔمِس کَن۔ \n48.\\tتہٕ حضرت عیسیٰ علیہ السلام دِیُت جواب تہٕ وونُن تِمَن زِ ژوٗرِ ہٕندِس خٕلافس پٲٹھۍ، تلوار تہٕ لورِ ہٮ۪تھ چھِو میہ نِنہٕ خٲطرٕ؟ \n49.\\tبہٕ اوسُس ژے سٍتـ̡ دۅہٕ سٍتـ̡ ہٕندِس درس مَنٛز روزان، تہٕ تہٕ ژے کٔرِو نہٕ مےٚ، مگر صحیفہٕ گژھہِ پورٕ کرنہٕ یُن۔ \n50.\\tتہٕ تِمو سارِوٕے ترٲوِتھ ژٔلِتھ ژٔلِتھ۔ \n51.\\tتہٕ اَتھ پَتہٕ أمِس پَتہٕ أکِس نوجوان، یُس کُنہِ \n52.\\tتہٕ تٔمۍ ترٲو کُن پلو تہٕ ژوٚل تِمو نِش ننگہٕ۔ \n53. تہٕ تِمو نِیہِ عیسیٰ مسیحس نِش بٔڈِس پادٕرِس نِش۔ تہٕ أمِس سٍتـ̡ گٔیہِ سارِنٕے سردار پادٕر، بزرگ تہٕ کاتب جمع ۔ \n54. تہٕ پطرس ووت أمِس پَتہٕ دوٗر تام تہٕ بٔڈِس پادٕرۍ سٕندِس محلس مَنٛز، تہٕ سُہ بِہتھ نوکرَن سٍتـ̡ تہٕ لوٚگ نارس نِش پان گرم۔ \n55.\\tتہٕ سارِوٕے پادٕرۍ تہٕ سارِوٕے مجلسو ژھانڈ عیسیٰ مسیحس خلاف گواہ حٲصل کرنہٕ خٲطرٕ۔ تہٕ لوٚبُکھ نہٕ کانہہ تہِ۔ \n56.\\tواریاہن گواہن ہٕندِس خلاف گٔیہِ اپُز گواہ، مگر تِہٕنزِ گواہ گٔیہِ نہٕ اِکہٕ وٹہٕ۔ \n57.\\tتہٕ تٔمِس خٕلاف گٔیہِ پُز گوٲہی دِنہٕ، تہٕ وَنُن زِ \n58.\\tاسہِ بوز سُہ یہِ ونان زِ بہٕ کرٕ یہِ مندر تباہ یُس اتھو سٍتـ̡ بناونہٕ آمُت چُھ، تہٕ ترٮ۪ن دۅہن اندر بناوٕ بہٕ بیاکھ اکھ اتھہٕ ورٲے بنوومُت۔ \n59.\\tمگر تِمن ہٕندِس گواہ سٍتـ̡ تہِ گٔیہِ اِکہٕ وٹہٕ اتفاق۔ \n60.\\tتہٕ بٔڈۍ پادٕرۍ ووٚتھ تھوٚد تہٕ حضرت عیسیٰ ہس پرژھن، تہٕ وونُن زِ ژے چھُکھ نہٕ کانہہ جواب دِوان؟ یِم گواہ کیا چِھہ؟ \n61.\\tمگر تٔمۍ تھوو خاموش تہٕ دیتُن نہٕ کانہہ جواب۔ بییہِ پرژھ تس اعلیٰ پادٕرین تہٕ وونُن تٔمِس زِ کیا تُہۍ چھُکھ مسیح سُند نیچو؟ \n62. تہٕ حضرت عیسیٰ علیہ السلام ووٚن، بہٕ چُھس: تہٕ ژے وُچھِو انسان سُند فرزند یُس طاقتہ کِس دچھنہِ اتھس پیٹھ بِہتھ تہٕ آسمانہٕ کِس اوٚبرس مَنٛز یِوان چھُ۔ \n63.\\tاَمہِ پتہٕ دِژ اعلیٰ پادٕرین پَنٕنـ̡ پَنٕنـ̡ تہٕ وَنُن زِ اسہِ کیا چُ \n64.\\tتوہین کفر بوزمُت: تۅہہ کیا خیال چُھ؟ تہٕ یِمو سارِوٕے کٔر أمِس موتُک مجرم قرار دِنٕچ مذمت۔ \n65.\\tتہٕ کینژو لوٚگ أمِس پیٹھ تھوکُن، تہٕ أمِس بُتھ تھپھ کٔرِتھ، تہٕ أمِس نِش وَنُن پیشن گوئی: تہٕ نوکرَو دِژ أمِس اتھو سٍتـ̡ تھپھ دِنہٕ۔ \n66. تہٕ یێلہِ پطرس محلس منز بۅنہ کنہِ اوس، تتہِ آو اعلیٰ پادٕرۍ سٕنزِ دٲیرِ منزٕ اَکھ دٲیر: \n67.\\tتہٕ ییلہ تٔمۍ پطرس پانس گرم کران وُچھ، تٔمۍ وُچھن أمِس کُن تہٕ وونُن، تہٕ تہٕ اوسُکھ حضرت عیسیٰ مسیحس سٍتـ̡ ناصری کِس سٍتـ̡ ۔ \n۶۸.\\tمگر تٔمۍ کٔر اِنکار، یہِ ؤنِتھ زِ بہٕ چھُس نہٕ پتاہ تہٕ بہٕ چھُس نہٕ سمجھان زِ ژےٚ کیا چُھ وَنان۔ تہٕ سُہ دراو دٲرِ منز۔ تہٕ کۅکر عملہٕ۔ \n۶۹.\\tتہٕ أکۍ دٲرِ وُچھ أمِس دُبارٕ تہٕ ہیوٚتُن تِمن وَنُن یِم اَکھ کھٔسِتھ کھڑا چھُ، یہِ چُھ تِمن مَنٛز اکھ۔ \n70.\\tتہٕ تٔمۍ کٔر بییہِ اَتھ نکار۔ تہٕ رژھ کھنڈ پَتہٕ یِمو پطرس ووٚن، یێلہِ تہٕ تُہۍ چُھکھ تِمن منزٕ اکھ، تہٕ تُہٕنز کتھ چھے اَتھ سٍتـ̡ متفق۔ \n71.\\tمگر تٔمۍ ہیوٚت بد دعا تہٕ قسم، {ونن}، بہٕ چُھس نہٕ أمِس شخصس زانان یٔمِس متعلق تُہۍ کتھ کران چھِ۔ \n72. تہٕ دۆیمہِ لٹہِ کۅکرِ ہُند عملہٕ۔ تہٕ پطرس کٔر سُہ لفظ یاد یُس حضرت عیسیٰ علیہ السلام أمِس ووٚنمُت، کۅکُر کۅکرِ دۄیہِ لٹہِ کۅکرِ برونہہ کُن، ژے کٔرِو میہ تریہ لٹہِ انکار۔ تہٕ ییلہ أمِس اتھ پیٹھ سونچ، سُہ رووُن۔ {ییلہ ...: یا، سُہ روو واریاہ زیادٕ، یا ہیوٚتُن وُن}","1. تہٕ صُبحٲے کٔر بٔڈۍ پادٕرین بزرگن تہٕ کاتبَن تہٕ سارِنٕے مجلسس سٍتـ̡ مشورٕ، تہٕ عیسیٰ ہس بٔنِتھ نِتھ تہٕ کوٚرُن پیلاطس نِش۔ \n2. تہٕ پیلاطس پرژھ أمِس زِ کیا تُہۍ چھُکھ یہودین ہُند بادشاہ؟ تہٕ تٔمۍ ووٚن أمِس جواب دِتھ، تہٕ تٔمۍ ووٚن تٔمِس وَنان۔ \n3.\\tتہٕ بٔڈۍ پادٕرین کٔر أمِس واریاہن چیزن ہُند الزام مگر تٔمۍ دِژ نہٕ کیٚنٛہہ تہِ جواب۔ \n4.\\tتہٕ پیلاطس پرژھ أمِس دُبارٕ یہِ زِ ژے چھُکھ نہٕ کانہہ جواب دِوان؟ وُچھِو تِم کٲژاہ کتھہِ ہٕنز گواہی دِوان چھِ۔ \n5.\\tمگر عیسیٰ علیہ السلام دیت نہ توتہِ کانہہ جواب۔ یێلہِ پۯاوُن پیلاطس حیران۔ \n6.\\tوۅنۍ دِژ تِمن خٲطرٕ اکھ قٲد، یُس تِم یژھان۔ \n7.\\tتہٕ اَکھ اوس بَرباس ناوُک، {یُس} اوس تِمن سٍتۍ بغاوت کٔرمٕژ، یِمو بغاوتس مَنٛز قتل کورمُت اوس۔ \n8.\\tتہٕ بٔڑۍ وُچھن وٲلِس ہجوم ہیوٚتُن تِمن سٍتـ̡ یِتھٕ پٲٹھۍ تٔمِس سٍتـ̡ کرُن یُس تِمن سٍتـ̡ کورمُت اوس۔ \n9.\\tمگر پیلاطس دیُت تِمن جواب دِتھ زِ کیا بہٕ یُس یہودین ہُند بادشاہ ژے نِش یلہٕ تراوُن؟ \n10.\\tتکیازِ تس ٲس پتاہ زِ بٔڈۍ پادٕرۍ چھِ أمِس حسد کٔرِتھ دِژمٕژ۔ \n11.\\tمگر بٔڈۍ پادٕرۍ کٔر لُکن ہُند جذبہٕ، زِ سُہ پَزِ تِمن نِش باراباس یلہٕ تراوُن۔ \n12. تہٕ پیلاطس دیُت جواب تہٕ وونُن تِمن دُبارٕ، تیلہِ کیا کٔرِو بہٕ تٔمِس سٍتـ̡ یُس تُہۍ یہودین ہُند بادشاہ ونان چھِو؟ \n13. تہٕ تِمو دِژ دُبارٕ کرٛٮ۪کھ دِنہٕ، أمِس کٔرِو صلیب دِنہٕ۔ \n14.\\tاَمہِ پَتہٕ ووٚن پیلاطس تِمَن کیازِ، تٔمِس کیا بُرکار چھُ کوٚرمُت؟ تہٕ تِمو دِژ زیادٕ کرٛٮ۪کھ دِنہٕ، أمِس کٔرِو صلیب دِنہٕ۔ \n15.\\tتہٕ یێلہِ پِلاطس یێلہِ لُکن رٲضی کرنہٕ خٲطرٕ تیار تہٕ دِژن حضرت عیسیٰ مسیح تِمن نِش یلہٕ تہٕ یێلہِ تٔمِس دِنہٕ خٲطرٕ دِژُن عیسیٰ مسیح دِنہٕ۔ \n16.\\tتہٕ سپاہ نِیہِ أمِس ہالس منز، یتھ پریٹوریم ونان چھِ۔ تہٕ تِم چھِ پوٗرٕ بینڈس اِکہٕ وٹہٕ بلاوان۔ {پریٹوریم: یا، محل، یا، سامعینن ہُند ہال}\n17.\\tتہٕ تِمو لوٚگ أمِس وانٛگُن رنٛگہٕ، تہٕ لوٚگُکھ کانٹَن ہُند تاج، تہٕ تھووُکھ تٔمِس کَلَس سٍتـ̡ \n18.\\tتہٕ ہیوٚتُن أمِس سلام، ہیلو، یہودین ہُند بادشاہ! \n19.\\tتہٕ تِمو لوٚگ أمِس کلَس پیٹھ لٔگِتھ تہٕ تھووُکھ أمِس کُٹھہِ کٔرِتھ تہٕ کٔرٕکھ أمِس پوٗزا کٔرِتھ۔ \n20.\\tتہٕ ییلہ تِمو أمِس ٹھٹھہٕ کٔر، تِمو کٔر أمِس نِش وانٛگُن رنٛگ تہٕ لوٚگُکھ أمِس پَنُن پَلَو، تہٕ دِژُکھ أمِس صلیب دِنہٕ خٲطرٕ۔ \n21.\\tتہٕ تِم چھِ أکِس شمعون سٕندِس مُلکَس منزٕ نیبر نیران، سِکندر تہٕ روفس سُند مول سُہ صلیب رٹنہٕ خٲطرٕ مجبور کران۔ \n22.\\tتہٕ تِم چھِ أمِس گولگوتھا جایہِ نِوان، یُس تشریح کرنہٕ آمُت چھُ، کلہٕ کھورِ ہٕنز جاے چھِ۔ \n23.\\tتہٕ تِمو دِژ أمِس مِرَس سٍتـ̡ شراب، مگر أمِس میلہِ نہٕ۔ \n24. تہٕ ییلہ تمو أمس مصلوب کٔر، تِمو ترٲو تٔمۍ سٕندِ پلو تہٕ تِمن پیٹھ پھٔٹِتھ یُس پرٮ۪تھ کانہہ انسان نِنہٕ یُن۔ \n25. تہٕ یہ اوس تریم گھنٹہٕ، تہٕ تمو کٔر أمس مصلوب۔ \n26.\\tتہٕ تٔمۍ سٕندِس الزامُک مُختٔلِف اوس لیکھنہٕ آمُت، یہودین ہُند بادشاہ۔ \n27.\\tتہٕ أمِس سٍتـ̡ چھِ زٕ چور صلیب دِوان۔ اکھ دچھنہِ اتھس پیٹھ، تہٕ بیاکھ کھوورِ طرفہٕ۔ \n28.\\tتہٕ صحیفہ سپُد پورٕ، یُس ونان چھُ، تہٕ سُہ آو گُنزراوَن سٍتـ̡ گنزراونہٕ۔ \n29.\\tتہٕ یِمو یُس اَتھ کُن گٔژھِتھ کلہٕ ہلٲوِتھ تہٕ وونُن، آہ، یُس مندر تباہ کٔرِتھ ترٮ۪ن دۅہن منز تعمیر کران چھُ، \n30. پَنُن پان بچٲوِو، تہٕ صلیب پیٹھٕ بۄن ؤسِو۔ \n31.\\tیتھے پاٹھۍ چھہ بڈۍ پادٕرۍ تہِ کاتبن سٍتۍ طنز کران ونان زِ تمۍ بچٲوۍ باقی۔ پانس بچٲوِتھ ہیکو نہ۔ \n32. اسرٲیلُک بادشاہ مسیح گژھہِ وۅنۍ صلیب پیٹھٕ وسُن، یُتھ أسۍ وُچھِتھ تہٕ پژھ کٔرِتھ۔ تہٕ یِمو أمِس سٍتـ̡ صلیب دِنہٕ آمٕژ ٲس، تِمو کٔر أمِس طعنہ دِنہٕ۔ \n33.\\tتہٕ ییلہ شیٚیِم گھنٹہٕ آو سٲرۍسٕے زمینس پیٹھ اوس نٔومہِ گھنٹس تام انہِ گوٚٹ۔ \n34.\\tتہٕ نٔوِمہِ بِژِ وِزِ حضرت عیسیٰ علیہ السلام وۆن بَڑِ آوازِ سٍتـ̡ وۆنُن، ایلوئی، ایلوئی، لاما سبچتھانی؟ یُس ترجمہٕ چُھہ کرنہٕ آمُت، میون خدا، میانہِ خدا، ژے کیازِ تروو میہ ترک؟ \n35.\\tتہٕ یِمو منزٕ کینہہ یِمو یِمو بوزِتھ ووٚن، وُچھِو سُہ الیاس ونان ۔ \n36.\\tتہٕ اَکھ ژوٚل تہٕ بٔرِتھ سِرکہٕ سٍتـ̡ بٔرِتھ تہٕ تھووُن أکِس نِلہٕ سٍتـ̡ تہٕ دِتُن چُھہ چُھہ دِنہٕ آمُت۔ اسہِ وُچھِو زِ الیاس یِنہٕ أمِس نِنہٕ خٲطرٕ۔ \n37.\\tتہٕ حضرت عیسیٰ علیہ السلام وۆن بَڑِ آوازِ سٍتـ̡ تہٕ ترووُن بھوت۔ \n38. تہٕ مندرُک پردہ آو ہیرٕ پیٹھٕ بۄن تام پھٹنہٕ۔ \n39.\\tتہٕ ییلہ أمِس خٕلاف کھڑا اوس، وُچھ زِ أمِس کٔر کرٛٮ۪کھ تہٕ ترووُن بھوت، تٔمۍ ووٚن، پٔزۍ پٲٹھۍ اوس یہِ انسان خدایہ سُند نیٚچُو۔ \n40.\\tاتہِ آسہٕ زنانہٕ تہِ دوٗر وُچھان: یِمن منز ٲس مریم مگدلینی، تہٕ مریم یۅسہٕ یعقوب سٕنز موج تہٕ جوسس تہٕ سالومی سٕنز موج ٲس۔ \n41. (یُس تہِ ییلہ سُہ گلیلس منز اوس، أمِس پتہٕ تہٕ أمِس خدمت کٔرٕن؛) تہٕ باقٕے واریاہ زنانہٕ یِم أمِس سٍتـ̡ یروشلم گٔیہِ۔ \n42.\\tتہٕ وُنہِ ییلہ تہِ ووت تہِ کیازِ یہ ٲس تیٲری یعنی سبت دۅہہ برونہہ، \n43. یوسف، یُس اَکھ معزز مُشیر اوس، یُس خدایہ سٕنزِ بادشٲہی ہُند پیاران اوس، آو تہٕ دِلیری سان پیلاطس نِش تہٕ کوٚرُن عیسیٰ سٕندِس جسمس ہُند طمع۔ \n44. تہٕ پیلاطس گوٚو حٲران زِ سُہ چھا گۄڈے موٗدمُت: تہٕ تٔمِس بُلٲوِتھ پُرٛژھ أمِس زِ سُہ چھا کُنہِ وِزِ موٗدمُت۔ \n45.\\tتہٕ ییلہ أمِس صد سٕندِس سٍتـ̡ پتاہ پتاہ اوس، تٔمۍ دِژ لاش یوسفس نِش۔ \n46.\\tتہٕ تٔمۍ ہیوٚت اصل کُن تہٕ نِن سُہ بۄن تہٕ لٔٹِتھ تہٕ تھووُن أکِس قبرس مَنٛز یُس أکِس کَنہِ کٔرِتھ اوس تہٕ لوٚگُن قبرٕ کِس دروازس تام۔ \n47. تہٕ مریم مگدلینی تہٕ مریم سٕنزِ ماجہ وُچھ سُہ کتہِ دِنہٕ آمُت۔","1. تہٕ ییلہ سبت دۅہ گزریو، مریم مگدلینی تہٕ یعقوب تہٕ سالومی سٕنزِ موج مریم ٲس مٔدٕر مسالہٕ ہیوٚتمٕژ، یُتھ تِم یِن أمِس مسح کٔرِتھ۔ \n2. تہٕ ہفتک گۅڈنچہ دۅہہ صبحٲے آیہ تم آفتاب کھسنہٕ وِزِ قبرس پیٹھ۔ \n3. تہٕ تِمو ووٚن پانہٕ پانہٕ، کُس کرِ اسہِ قبرٕ کِس دروازٕ پیٹھٕ کٔنہِ کٔنہِ؟ \n4. تہٕ ییلہ تمو وُچھ، تمو وُچھ زِ کنہِ ٲس لٔٹِتھ لٔٹِتھ، تکیازِ یہ اوس واریاہ بوٚڈ۔ \n5.\\tتہٕ قبرس منز اژِتھ وُچھ تِمو دٔچھنِس طرفہٕ اکھ نوجوان بِہِتھ، یُس زیوٗٹھ سفید پلو لٲگِتھ اوس۔ تہٕ تِم گٔیہِ خوفزد۔ \n6. تہٕ سُہ چُھ تِمن ونان زِ خوفزدہ گژھ نہٕ: تم چھو عیسیٰ مسیح سٕنز تلاش کران، یُس صلیب اوس دِنہٕ آمُت: سُہ چُھ زندٕ گومُت۔ سُہ چُھ نہٕ یتہِ چُھ: وُچھِو سُہ جاے ییتہِ تمو دِنہٕ آمُت۔ \n7. مگر پَنٕنـ̡ پۯاوُن، تٔمۍ سٕندِس شاگردن تہٕ پطرس ؤنِو زِ سُہ چُھہ تۅہہِ برونہہ کُن گلیلِس مَنٛز، تتہِ وُچھِو سُہ یِتھٕ پٲٹھـ̡ تٔمۍ ژےٚ وُچھمُت۔ \n8.\\tتہٕ تِم ژٔلِتھ ژٔلِتھ قبرٕ پیٹھ۔ تِم گٔیہِ تھرِ تھرِ تہٕ حٲران گٔیہِ: تِمو ووٚن نہٕ کٲنسہ تہِ انسانس کُنہِ تہِ۔ تِکیازِ تِم ٲسۍ کھوژان۔ \n9. وۅنۍ ییلہ {عیسیٰ مسیح} ہفتہٕ کس گۄڈنِکِس دۅہس منز زندٕ گوو، سُہ آو گۅڈنچہ لٹہِ مریم مگدلینی نِش ظٲہر، ییمہِ منزٕ تٔمۍ ستھ شیطان تراوۍ مٕتۍ۔ \n10.\\t{تہٕ} سۅ گٔیہِ تہٕ وونُن تِمن سٍتـ̡ یێلہِ تِم ٲسۍ ماتم تہٕ رووُن۔ \n11. تہٕ تِمو ییلہ یہ بوز زِ سُہ چُھ زندٕ، تہٕ أمِس وُچھمُت اوس، تِمو کٔر نہٕ پژھ۔ \n12.\\tتمہ پتہ آو سُہ بییہ أکِس شکلہِ منز یِمو منزٕ دۅن برونہہ کُن نمودار، ییلہ تِم پکان ٲسۍ، تہٕ گٔیہ ملکس منز۔ \n13.\\tتہٕ تِمو گٔے تہٕ وونُن باقیاتس کُن: نَہ تہٕ تِمو پژھ کٔرِتھ۔ \n14.\\tامہ پتہ آو سُہ کاہَن نِش ظٲہر ییلہ تِم مازس پیٹھ بِہتھ ٲسۍ، تہٕ تِمن کُفر تہٕ دِل سختی سٍتـ̡ دِژٕن، تکیازِ تِمو اوس نہٕ تِمن پیٹھ یقین یِمو أمِس زندٕ گژھنہٕ پتہٕ وُچھمُت اوس۔ {مازس پیٹھ: یا یکوٹے}\n15.\\tتہٕ تٔمۍ ووٚن تِمَن سارِنٕے دُنیاہس مَنٛز گٔژِھتھ تہٕ پرٮ۪تھ کُنہِ مخلوقس سٍتـ̡ انجیل دِنٕچ تبلیغ کٔرِو۔ \n16. یُس ایمان تھاوان تہٕ بپتسمہ دِیہِ سُہ گژھہِ نجات دِنہٕ۔ مگر یُس نہٕ ایمان تھاوان آسہِ سُہ گژھہِ لعنت کرنہٕ۔ \n17. تہٕ یِم نشانہٕ گژھن تِمن ہٕندِس پَتہٕ یِمن ہٕندِس پٲٹھۍ۔ میانہِ ناوٕ سٍتـ̡ کٔرِن تِم شیطان کٔڑِتھ؛ تِم کٔرِن نٔوۍ زبانہٕ سٍتـ̡ کتھ کرنہٕ۔ \n18.\\tتِم رٔٹِن ناگ۔ تہٕ اگر تِم کانہہ مہلک چیز چیٚن، تِمن گژھِ نہٕ تِمن تکلیف دِنہٕ۔ تِم گژھن بیمارن پیٹھ اتھہٕ تھٲوِتھ، تہٕ تِم گژھن ٹھیٖک گَژھان۔ \n19.\\tتێلہِ ییلہ خداوند تِمن سٍتـ̡ کتھ کٔر، سُہ آو اسمانس مَنٛز نِنہٕ، تہٕ بیوٹھ خدایہ سٕندِس دچھنہِ اتھس پیٹھ۔ \n20. تہٕ تِمو درٛاو تہٕ کُنہِ جایہِ تبلیغ کٔرِتھ، خداوند کٔرٕن تِمن سٍتـ̡ کٲم کٔرِتھ، تہٕ کٔرٕن کلامٕچ تصدیق کٔرِتھ یِمن ہٕندِس نشانہٕ سٍتـ̡ ۔ آمین۔"];
